(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-enhancing-large-language-model-effic-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-1\">一 · 现场：一次仓库级补全请求的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-2\">二 · 旧方案一：量化压的是位宽，不是冗余</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-3\">三 · 旧方案二：剪枝与驱逐，语义等价无从核验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-4\">四 · 旧方案三：前缀缓存的正交盲区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-5\">五 · 为什么非改不可：预填算力与驻留的双重挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-6\">六 · 符号压缩在预填前的收益边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-7\">七 · 输入长度分布：压缩层真正吃的是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-8\">八 · 并发与批大小：符号表是共享状态，不是每请求私有</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-9\">九 · SLO 与长尾：展开延迟必须进首 token 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-10\">十 · 负载塑造方案：重复度决定压缩层是否值得开</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-11\">十一 · 方案反过来限制负载：符号表容量即并发上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-12\">十二 · 测量口径清单：把不可核验的结论变成可核验的埋点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-13\">十三 · 符号压缩在负载形态下的边界：何时省、何时反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-14\">十四 · 压缩上下文进入 kernel 时的形状问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-15\">十五 · 数据类型选择：从 BF16 到 NVFP4 的逐级让渡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-16\">十六 · 累加精度与 tcgen05 的累加器位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-17\">十七 · TMEM 容量与符号表驻留的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-18\">十八 · 一个仓库级补全的具体走位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-19\">十九 · 符号展开路径上的算子代价与数值边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-20\">二十 · 显存账本的三层结构与符号压缩的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-21\">二十一 · KV 账的可复算预算：从字节公式到并发上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-22\">二十二 · 分页与复用：符号表作为前缀缓存元数据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-23\">二十三 · 压缩、卸载与带宽瓶颈的真实位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-24\">二十四 · 符号表容量上限与膨胀的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-25\">二十五 · 与量化、分离式预填叠加时的账本重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-26\">二十六 · 符号压缩的显存账本边界：驻留窗口、符号表开销与回退代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-27\">二十七 · 符号压缩上下文进入调度器的形态变化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-28\">二十八 · Chunked prefill 与展开窗口的粒度对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-29\">二十九 · 优先级、抢占与符号表的引用计数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-30\">三十 · 分离式预填/解码下的符号表放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-31\">三十一 · 尾延迟的压缩路径与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-32\">三十二 · 符号压缩在调度层的失效边界与批处理代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-33\">三十三 · 切分维度与符号压缩的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-34\">三十四 · NVLink 5 与 NVSwitch：带宽账与拓扑选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-35\">三十五 · All-to-All 与 EP：符号表归属决定瓶颈位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-36\">三十六 · PP 与 DP：边界传递与副本冗余</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-37\">三十七 · NIXL 传输与分离式拓扑下的通信路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-38\">三十八 · 符号表元数据在 TP/EP/PP/DP 切分下的通信边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-39\">三十九 · 精度塌陷：还原校验是唯一的硬闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-40\">四十 · OOM 与符号表膨胀：容量上限要和批大小联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-41\">四十一 · 批抖动与尾延迟：展开开销进入首 token 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-42\">四十二 · 静默降级：三类信号必须同时看</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-43\">四十三 · 回滚：分级回退而非全局关闭</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-44\">四十四 · 失效边界：从还原校验到符号表膨胀的工程诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-45\">四十五 · 论文口径的空缺：没有数字时如何建立可读的基准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-46\">四十六 · 硬件档位：B200/B300 与 NVL72 上三笔代价的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-47\">四十七 · batch 与并发：符号表容量与展开窗口联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-48\">四十八 · 指标分解：TTFT、TPOT、吞吐、显存、功耗各自归谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-49\">四十九 · 哪些提升不可比：四类口径陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-50\">五十 · 自建基准的最小清单与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-51\">五十一 · 迁移到非代码负载：符号密度决定收益上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-52\">五十二 · 与量化、前缀缓存叠加时的次序与冲突</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-53\">五十三 · 规模上限：符号表容量 M 与并发批大小的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-54\">五十四 · 不适用的边界：语义等价无法规则化的场景</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-55\">五十五 · 部署决策：三条可执行的判断线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-large-language-model-effic-2025-sec-56\">五十六 · 迁移的代价在规则面，不在算子面</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:590px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后先做长度与重复度统计，识别可符号化的代码块与文档片段。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">模式匹配生成符号表，重复片段替换为符号引用，残差序列保留不可压缩部分。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">压缩上下文送入预填阶段，仅对残差与符号表计算注意力，减少预填 toke…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码时按符号引用惰性展开为原始片段，KV cache 仅驻留当前活跃展…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">符号表作为元数据参与前缀缓存命中判断，仓库级复用直接复用符号表而非原文。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出前做符号还原校验，保证展开结果与原始语义一致并记录压缩失败模式。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-1\">一 · 现场：一次仓库级补全请求的显存账</h3>\n<p>设想一个部署在 GB200 NVL72 机架上的代码补全服务：某 IDE 插件把当前文件、同目录的若干文件、跨包的接口定义与最近几轮工具调用结果一并塞进请求，单请求上下文动辄数十 K token。请求进入预填阶段时，注意力计算要对整段序列做一次前向，KV cache 则按序列长度线性驻留——这是这条推理链路上最刚性的一笔开销。仓库级场景的麻烦在于，相邻请求携带的上下文高度重叠：同一个函数签名、同一段注释模板、同一份类型定义在几十个请求里反复出现，而主流推理栈对这份重叠的处理方式是“照单全收、逐份预填”。前缀缓存能救一部分，但它只认完全相同的前缀，跨文件重排、编辑片段插入、工具调用轮次变化都会让命中率塌下来。</p>\n<p>把账算清楚：设序列长度为 <span class=\"inline-math\">L</span>、层数为 <span class=\"inline-math\">N_l</span>、KV 头数为 <span class=\"inline-math\">H</span>、头维为 <span class=\"inline-math\">d</span>、每元素字节数为 <span class=\"inline-math\">b</span>，则单请求 KV 驻留为</p>\n<div class=\"formula\">$$\\mathrm{KV}_{\\text{bytes}} = 2 \\cdot N_l \\cdot H \\cdot d \\cdot L \\cdot b$$</div>\n<p>系数 2 来自 K 与 V 两份。这个式子的关键性质是它对 <span class=\"inline-math\">L</span> 线性、对并发批大小线性。在连续批处理下，驻留成本是两者之积；在分离式预填/解码拓扑里，预填节点承担的是 <span class=\"inline-math\">O(L^2)</span> 的注意力算力，解码节点承担的是随批增长的带宽压力。仓库级上下文的重复度越高，这两笔开销里被浪费的比例就越大——重复片段既被重复预填，又被重复驻留。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-2\">二 · 旧方案一：量化压的是位宽，不是冗余</h3>\n<p>Blackwell 上最直接的省显存手段是降精度。NVFP4 把权重与激活压到 4 位块浮点，FP8 用于 KV 与注意力中间结果，tcgen05 的 MMA 指令与 TMEM 承担高吞吐矩阵乘，2-SM MMA 让一对 SM 协同完成更大规模的乘加。这套组合把每元素字节数 <span class=\"inline-math\">b</span> 从 2 压到 1 甚至 0.5，直接线性缩小上面的 KV 式子。代价是数值层面的：KV 量化引入的误差在长上下文里累积，需要 per-channel 或 per-block 的缩放因子管理，而缩放因子本身又是元数据开销。</p>\n<p>问题在于量化压的是“每个 token 占多少位”，不是“有多少 token 是重复的”。一个在 40 个请求里各出现一次的函数体，量化后仍然要存 40 份、预填 40 次。量化与前缀缓存叠加时收益是乘性的，但两者都触不到“同一段内容在语义上只需存一份”这一层。工程上这意味着：即便把 KV 压到 FP8，长上下文请求的驻留曲线依然随 <span class=\"inline-math\">L</span> 线性上扬，容量规划仍要按最坏长度留余量，SLO 下的并发上限被显存而非算力卡住。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-3\">三 · 旧方案二：剪枝与驱逐，语义等价无从核验</h3>\n<p>第二类做法是剪枝与 KV 驱逐：按注意力分数、按最近使用窗口、按结构边界丢弃部分 token 的 KV。这类方法在解码阶段确实能压住驻留，但它做的是一个不可逆的丢弃决策——被驱逐的 KV 无法还原，模型后续若需要该片段，只能重算或接受语义漂移。对代码补全这种要求“补出来的标识符必须与仓库里定义的一致”的任务，漂移是不可接受的：丢掉一个类型定义，模型就可能编出一个不存在的字段名。</p>\n<p>更麻烦的是可解释性。剪枝策略给出的依据是注意力权重或启发式窗口，工程上无法回答“为什么这段被丢、那段被留”，也无法在输出前做一次可核验的等价性检查。论文针对的正是这个缺口：现有量化与剪枝手段难以在保持语义等价的同时给出可解释的压缩依据，缺乏形式化保证。这句话在工程上翻译过来就是——你可以把显存压下去，但你没法证明压完之后模型看到的还是原来那段上下文。</p>\n<ul>\n<li>量化：压位宽，收益线性但触不到冗余，误差需缩放因子管理。</li>\n<li>剪枝/驱逐：压 token 数，但丢弃不可逆，语义等价无核验手段。</li>\n<li>前缀缓存：只认完全相同前缀，跨文件重排与编辑插入导致命中率下降。</li>\n</ul>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-4\">四 · 旧方案三：前缀缓存的正交盲区</h3>\n<p>前缀缓存是仓库级复用最贴近需求的一招：把已预填前缀的 KV 存下来，命中则跳过预填。它在分离式预填/解码拓扑里尤其有价值，因为预填节点最贵的就是那段 <span class=\"inline-math\">O(L^2)</span> 算力。但它的匹配是字节级或 token 级的前缀相等，一旦请求在开头插入了本轮特有的编辑片段，或者跨文件上下文顺序变了，命中就失效。真实仓库请求的形态恰恰是“大段相同、局部不同”，前缀缓存对这种形态的利用率不高。</p>\n<p>论文的压缩层把可复用单元从“前缀”下沉到“片段”：重复出现的代码结构与自然语言片段被抽象为符号引用，符号表与残差序列共同构成压缩上下文。这样即使请求开头不同，只要符号表命中，跨请求仍可复用同一份元数据，避免重复预填。这与前缀缓存正交——前者管片段级复用，后者管前缀级复用，两者可叠加。代价是符号表本身要占显存与查找开销，且符号边界识别错误会产生展开歧义。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-5\">五 · 为什么非改不可：预填算力与驻留的双重挤压</h3>\n<p>把三条旧路径放在一起看，缺口很清楚：量化降的是单位成本，剪枝降的是数量但不可逆，前缀缓存降的是重复预填但匹配粒度太粗。仓库级上下文复用与工具调用循环把这三个缺口同时放大——agent 循环里同一份工具返回结果被反复带入，每一轮都要重新预填、重新驻留。预填算力浪费与 KV 膨胀是同一份冗余在两个层面的投影。</p>\n<p>论文的形式化约束给出的是一条不同的路：压缩必须可逆，<span class=\"inline-math\">\\(\\mathrm{Expand}(\\mathcal{C}(x))=x\\)</span>，输出前做还原校验，失败则回退原文路径。这条约束把“压缩”从启发式丢弃变成了可核验的映射，代价是规则维护与符号表管理，收益是 token 流与 KV 层同时削减冗余。对已部署模型无需重训或微调，这一点对工程侧很关键——它意味着可以在不改动权重与量化方案的前提下，把压缩层插在请求进入预填之前。</p>\n<p>但这条路的工程风险同样具体：符号边界识别依赖人工规则，跨语言与跨仓库易产生展开歧义；符号表容量上限 <span class=\"inline-math\">M</span> 触发按复用频次淘汰低频符号，膨胀会抵消压缩收益；符号展开开销要纳入首 token 时延预算，超限时回退原文以保证 SLO。材料未给出任何吞吐、延迟或压缩率数字，因此这套机制能否在 B200/B300 档位下真正省下显存，取决于符号表容量与并发批大小的联合标定，而不是论文的定性声称。</p>\n<p>一个可操作的判断标准是：在给定 SLO 下，先测出预填 token 中重复片段的占比与符号表命中率，若命中率不足以覆盖符号表驻留与展开延迟，压缩层就是净亏；反之，它提供的是一条与 NVFP4/FP8 量化、前缀缓存、分离式预填都能叠加的削减路径，且因为可逆性约束而具备可核验性——这正是旧方案给不了的东西。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-6\">六 · 符号压缩在预填前的收益边界与失效条件</h3>\n<p>把压缩层插在请求进入预填之前，收益并非无条件成立。设原始序列长度为 <span class=\"formula-inline\">L</span>、残差长度为 <span class=\"formula-inline\">L_r</span>、符号表条目数为 <span class=\"formula-inline\">n</span>、每条符号平均展开长度为 <span class=\"formula-inline\">\\(\\bar{l}\\)</span>，则预填阶段实际参与注意力的 token 量为 <span class=\"formula-inline\">L_r + n</span>，而解码时活跃 KV 覆盖的窗口为 <span class=\"formula-inline\">W</span>。压缩收益成立的前提是 <span class=\"formula-inline\">\\(L_r + n \\ll L\\)</span> 且 <span class=\"formula-inline\">\\(W \\ll L\\)</span>。这两个不等式在仓库级代码补全里容易满足：跨文件重复的函数签名、许可证头、注释模板、样板 import 块都是高重复度片段，符号化后残差只剩本次编辑特有的几行。但在通用长文本推理中，重复片段稀疏且边界模糊，<span class=\"formula-inline\">L_r</span> 逼近 <span class=\"formula-inline\">L</span>，压缩层反而增加一次全序列扫描的开销，预填 token 量不降反升。这就是该方案的第一个边界：它吃的是结构重复度，不是序列长度本身。</p>\n<p>第二个边界在符号表容量。设容量上限为 <span class=\"formula-inline\">M</span>，按复用频次淘汰低频符号。当仓库规模扩大、跨文件符号种类增长快于复用频次集中度时，符号表本身成为驻留成本：符号表要作为元数据参与前缀缓存命中判断，意味着它必须常驻或至少可快速索引，其内存占用与 <span class=\"formula-inline\">M</span> 成正比。若 <span class=\"formula-inline\">M</span> 设得过小，高频符号被淘汰后需回退原文路径，预填节省被侵蚀；设得过大，符号表膨胀抵消 KV 节省，且前缀缓存命中判断的元数据比对开销上升。工程上需把 <span class=\"formula-inline\">M</span> 与并发批大小联合标定：批内请求共享符号表时摊销成本低，批间符号表差异大时每个请求都要携带自己的符号表视图，元数据带宽成为新瓶颈。</p>\n<p>第三个边界是展开延迟对首 token 时延的挤压。解码遇到符号引用需惰性展开，展开操作本身是查表加拼接，单次开销小，但在工具调用循环与 agent 多轮场景中，符号引用密集出现，展开次数随轮次累积。代码补全要求低延迟，符号展开开销必须纳入首 token 时延预算；一旦展开路径的时延超过 SLO 上限，系统需回退原文路径，此时压缩层的工作全部作废，等于白付一次扫描成本。更棘手的是符号边界识别错误：人工规则在跨语言、跨仓库时易把不该合并的片段抽象为同一符号，展开后语义偏移，虽可由 <span class=\"formula-inline\">\\(\\mathrm{Expand}(\\mathcal{C}(x))=x\\)</span> 的还原校验兜底，但校验失败即触发回退，回退率上升直接吃掉吞吐收益。表 1 给出三类场景下压缩层是否值得启用的判断依据。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>重复片段密度</th><th>符号表稳定性</th><th>展开频率</th><th>工程判断</th></tr></thead><tbody><tr><td>仓库级代码补全</td><td>高</td><td>高（跨请求复用）</td><td>中</td><td>启用，收益主要来自预填 token 削减</td></tr><tr><td>通用长文本问答</td><td>低</td><td>低</td><td>低</td><td>不启用，扫描开销大于节省</td></tr><tr><td>Agent 工具调用循环</td><td>中</td><td>中（跨轮复用）</td><td>高</td><td>启用但需设展开延迟上限与回退阈值</td></tr></tbody></table>\n<p>系统代价还体现在规则维护上。该方法不依赖训练或微调，规则由人工设定，可直接作用于已部署模型，代价集中在规则维护与符号表管理而非梯度计算。这与量化、前缀缓存的性质不同：NVFP4/FP8 量化是一次性标定后全局生效，前缀缓存是运行时自动命中，而符号压缩的规则集需要随代码库演进持续维护，跨语言泛化性未经验证。监控必须覆盖符号还原失败率、符号表膨胀速率与预填 token 节省比例三项指标，任一指标恶化即应收缩压缩层的作用范围。材料未给出任何吞吐、延迟或压缩率数字，因此不能把该方案当作默认开启的优化项；正确做法是在具体硬件档位与 SLO 下，先用小流量灰度测出回退率与展开延迟分布，再决定是否把它叠加在分离式预填/解码拓扑之上。</p>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-7\">七 · 输入长度分布：压缩层真正吃的是什么</h3>\n<p>符号压缩的收益不取决于平均输入长度，而取决于长度分布里“可符号化片段”的占比。仓库级代码补全的请求通常由三部分拼成：跨文件上下文（签名、类型定义、注释模板）、本次编辑窗口、以及工具调用留下的历史。前两部分重复度高，是符号表的原料；第三部分随轮次增长且重复度低，属于残差。工程上必须把这三段分开统计，否则“平均 32K 输入”这种口径会把压缩层的真实工作面掩盖掉。</p>\n<p>可核查的测量口径是：对每条请求记录 <em>总 token 数</em>、<em>符号识别命中片段数</em>、<em>被替换 token 数</em>、<em>残差 token 数</em>，并按 P50/P90/P99 分位输出压缩比 $|x|/|\\mathcal{C}(x)|$。压缩比的分位分布比均值更有意义——长尾请求往往正是符号表膨胀的来源。设单请求压缩后预填量为</p>\n<div class=\"formula\">$$T_{\\text{prefill}} = |r| + |\\mathcal{S}_{\\text{active}}|,\\qquad |r| = |x| - \\sum_{i \\in \\text{hits}} |s_i|$$</div>\n<p>其中 $|\\mathcal{S}_{\\text{active}}|$ 是本次请求实际引用到的符号条目数，而非符号表全量。这个区分决定了预填算力账怎么算：符号表本身也要过注意力，全量挂载会让压缩收益被元数据吃掉。代价侧，预填 FLOPs 大致随 $T_{\\text{prefill}}$ 线性走，而 KV 驻留随解码活跃窗口走；两者不是同一个量，监控必须分开埋点。</p>\n<p>具体例子：一次跨文件重构请求携带 12 个文件的函数签名与 3 段重复注释模板，符号层把这些抽成符号引用后残差只剩编辑窗口与调用历史；若不做分段统计，运维只会看到“输入变短了”，却无法判断缩短来自符号化还是来自客户端截断。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-8\">八 · 并发与批大小：符号表是共享状态，不是每请求私有</h3>\n<p>连续批处理把不同请求拼进同一 step，符号压缩在这里引入一个非典型约束：符号表是跨请求可复用的元数据，批内多个请求可能命中同一符号。若每个请求各自持有一份符号表副本，显存随批大小线性膨胀；若共享，则批内符号引用需要统一寻址，展开窗口的活跃 KV 也要按符号粒度去重。工程判断是：符号表按仓库/租户维度做单例驻留，批内请求只持引用计数，淘汰由全局容量上限 $M$ 驱动。</p>\n<p>伪代码思路：</p>\n<ul>\n<li>批装配阶段先做符号命中归并，把批内引用同一符号的请求聚成组，展开时只算一次该符号的 KV；</li>\n<li>活跃 KV 预算按 $\\sum_{\\text{groups}} |\\text{expand}(s)|$ 而非按请求数估算；</li>\n<li>当批内符号组数超过阈值，降批大小而不是降符号表容量——后者会破坏跨请求复用。</li>\n</ul>\n<p>吞吐代价体现在两处：一是批装配多了一次符号归并的 CPU/元数据开销，属于每 step 固定成本，批越大摊得越薄；二是展开窗口去重后，单 step 的有效 token 数下降，GPU 利用率可能反而变差，需要用更大的批来补。显存侧，符号表驻留 $M$ 条目的元数据与展开缓存是常驻项，必须从 KV 预算里先扣除再算最大并发。具体例子：NVL72 单节点上多租户代码服务，若符号表按租户单例驻留，租户数增加会直接压缩可分配给活跃 KV 的空间，容量规划要把符号表当作与权重同级的常驻项。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-9\">九 · SLO 与长尾：展开延迟必须进首 token 预算</h3>\n<p>代码补全的 SLO 通常压在首 token 时延上，而符号展开发生在解码路径里：遇到符号引用要查表、取片段、拼回注意力窗口。这条路径的延迟不由 GPU 算力决定，而由符号表查找与展开拷贝决定，属于 CPU 侧与显存带宽侧的混合开销。可核查口径是把首 token 时延拆成 <em>排队</em>、<em>预填</em>、<em>首次展开</em> 三段分别打点，展开段单独设上限；超限即回退原文路径，用未压缩上下文直接预填，牺牲显存换 SLO。</p>\n<p>长尾的来源不是长输入本身，而是“符号边界识别失败”的请求：规则匹配在跨语言、跨仓库风格差异下会产生歧义，还原校验 $\\mathrm{Expand}(\\mathcal{C}(x))=x$ 不通过就得整条回退。这类请求的代价是双倍的——先做了一遍符号识别与校验，再走一遍原文预填。监控必须记录 <em>还原失败率</em> 与 <em>回退率</em>，并把回退请求的时延单独分位统计，否则 P99 会被这批请求主导而无法归因。</p>\n<p>具体例子：agent 工具调用循环中，同一符号表跨轮复用，第二轮起预填量显著下降；但若某轮工具返回的代码片段破坏了符号边界，校验失败触发回退，该轮首 token 时延反而高于无压缩基线。SLO 设计要把这种“压缩路径偶发更慢”的情形纳入预算，而不是假设压缩永远单调变快。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-10\">十 · 负载塑造方案：重复度决定压缩层是否值得开</h3>\n<p>负载形态反过来筛选方案。符号压缩的收益与上下文重复度强相关：仓库级代码上下文中函数签名、类型声明、注释模板的重复比例高，符号化命中率高；通用长文本推理、自由形式对话的重复度低，符号表命中稀疏而元数据开销照付，压缩比接近 1 却多了查表与校验成本。工程判断是给压缩层设一个准入条件：按请求的重复度统计（命中片段 token 占比）决定是否走符号路径，低于阈值直接原文预填。</p>\n<p>这条准入规则本身要可测量：以滑动窗口统计最近 N 条请求的 <em>命中 token 占比</em> 与 <em>符号表膨胀速率</em>，前者低于阈值则关闭压缩，后者超过容量上限 $M$ 的增速则触发按复用频次淘汰低频符号。淘汰会带来二次代价——被淘汰符号若再次出现，需重新识别并可能错过前缀缓存命中，因此淘汰策略要与缓存 TTL 联合标定，而不是独立调参。</p>\n<p>具体例子：同一套部署同时服务代码补全与文档问答，前者命中占比高、压缩后预填 token 明显下降；后者命中稀疏，开启压缩只增加展开与校验开销。按请求类型分流，而不是全局开关，是这套方案在混合负载下的正确形态。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-11\">十一 · 方案反过来限制负载：符号表容量即并发上限</h3>\n<p>压缩方案对负载有反向约束，最直接的是符号表容量 $M$ 与并发批大小的耦合。符号表常驻显存、展开缓存按活跃窗口占用，两者之和构成不可压缩的底噪；剩余空间才轮到 KV 与批。于是最大并发不是由模型权重决定，而是由 $M$ 与展开窗口大小决定。容量规划的顺序应是：先定 $M$（按仓库规模与复用频次分布），再定单请求展开窗口上限，最后反解可支撑的并发与批大小。</p>\n<p>可核查口径：记录 <em>符号表占用显存</em>、<em>展开缓存占用</em>、<em>活跃 KV 占用</em> 三项的实时分位，以及 <em>符号表命中率</em> 与 <em>淘汰率</em>。当淘汰率上升而命中率不升，说明 $M$ 偏小或负载重复度下降，此时扩并发只会加剧抖动。功耗侧，符号化降低的是预填算力而非解码算力，解码仍是逐 token 自回归，功耗下降幅度受解码占比限制；长输入短输出的补全负载受益明显，长输出负载受益有限。</p>\n<p>具体例子：GB200 NVL72 上做仓库级服务，若把 $M$ 设得过大以追求高命中，符号表常驻会挤掉活跃 KV，批大小被迫下调，吞吐反降；把 $M$ 收紧并配合按频次淘汰，命中率略降但并发上升，端到端吞吐更优。这个权衡点只能实测，材料未给出定量结果，因此必须以本文给出的三项占用分位与命中/淘汰率作为标定依据，而不是引用论文的效率结论。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-12\">十二 · 测量口径清单：把不可核验的结论变成可核验的埋点</h3>\n<p>该论文未给出数据集、基线与定量结果，因此工程落地时唯一可靠的做法是把它的机制翻译成一组可核验埋点，用自测数据替代论文结论。下表给出最小口径集合，每项都要按 P50/P90/P99 分位输出，并与关闭压缩的对照组同口径对比。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>定义</th><th>影响的系统代价</th></tr></thead><tbody>\n<tr><td>压缩比</td><td>$|x|/|\\mathcal{C}(x)|$，按请求分位</td><td>预填 token 量与预填算力</td></tr>\n<tr><td>命中 token 占比</td><td>被符号替换 token / 总 token</td><td>压缩是否值得开启的准入判据</td></tr>\n<tr><td>符号表占用</td><td>元数据常驻显存，按 $M$ 与条目大小估</td><td>挤压活跃 KV 与最大并发</td></tr>\n<tr><td>展开窗口均值/峰值</td><td>解码时活跃展开片段 token 数</td><td>KV 驻留与显存带宽</td></tr>\n<tr><td>还原失败率/回退率</td><td>校验不通过请求占比</td><td>长尾时延与双倍预填成本</td></tr>\n<tr><td>首 token 展开段时延</td><td>查表+展开拷贝耗时</td><td>SLO 预算与回退阈值设定</td></tr>\n<tr><td>符号表膨胀速率与淘汰率</td><td>单位请求新增条目数、淘汰条目数</td><td>$M$ 标定与缓存 TTL 联合调参</td></tr>\n</tbody></table>\n<p>这张表的关键在于把“效率提升”拆成可归因的分项：预填节省来自压缩比与命中占比，显存节省来自展开窗口而非序列长度，长尾恶化来自还原失败率。任何一项单独变好都不足以证明方案有效——例如压缩比高但展开窗口峰值大，KV 节省会被抵消；命中率高但符号表膨胀快，常驻显存会吃掉并发收益。工程判断落在准入阈值与 $M$ 的联合标定上：以命中 token 占比作为开关判据，以符号表占用分位作为并发上限的反解输入，以还原失败率作为回退阈值的触发条件，三者共同决定这套符号压缩在具体硬件档位与 SLO 下是否净收益为正。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-13\">十三 · 符号压缩在负载形态下的边界：何时省、何时反噬</h3>\n<p>符号压缩的收益不是请求无关的常数，而是输入长度分布、跨请求重复度与并发批大小的函数。设单请求原始 token 数为 <span class=\"inline-math\">L</span>，可符号化片段占比 <span class=\"inline-math\">ρ</span>，符号表条目数为 <span class=\"inline-math\">n</span>、每条目平均展开长度为 <span class=\"inline-math\">ℓ</span>，则预填 token 量近似从 <span class=\"inline-math\">L</span> 降为 <span class=\"inline-math\">(1−ρ)L + n</span>，而解码期活跃 KV 驻留量由整段 <span class=\"inline-math\">L</span> 收缩到展开窗口 <span class=\"inline-math\">W</span>。压缩率因此写成</p>\n<div class=\"formula\">$$R=\\frac{L}{(1-\\rho)L+n},\\qquad \\text{KV 驻留}\\propto W\\ \\text{而非}\\ L$$</div>\n<p>这个式子暴露了失效条件：当 <span class=\"inline-math\">ρ</span> 低（通用长文本、散文式对话）时分子分母接近，压缩只带来规则匹配与还原校验的纯开销；当 <span class=\"inline-math\">n</span> 随仓库规模增长而 <span class=\"inline-math\">ρ</span> 不增时，符号表本身成为新的驻留负担。仓库级代码补全恰好落在 <span class=\"inline-math\">ρ</span> 高、<span class=\"inline-math\">n</span> 有界的区间，这是该方法适用面的真实边界，而非“长上下文”这一泛化标签。</p>\n<p>负载反过来也被方案塑形。符号表容量上限 <span class=\"inline-math\">M</span> 触发按复用频次淘汰低频符号，意味着高并发下批内不同请求争用同一符号表缓存槽位：批大小越大，符号表命中前缀缓存的概率越高、单请求摊销的预填越少，但一旦某请求的符号在批内被淘汰，其解码路径被迫回退原文，首 token 时延（TTFT）出现长尾。可核查的测量口径必须把这条长尾单独切出来：按 <span class=\"inline-math\">ρ</span> 分桶统计 TTFT 的 P50/P99、记录还原校验失败率与回退原文比例、记录符号表膨胀速率（条目数/请求数）与预填 token 节省比例，四者联合才能判断收益是否被规则维护与展开开销吃掉。SLO 上应给符号展开延迟设硬上限，超限即回退，把不确定性挡在延迟预算之外。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>压缩收益</th><th>主要代价</th></tr></thead><tbody><tr><td>高重复、跨文件代码上下文</td><td>预填 token 与 KV 驻留同步下降</td><td>符号边界误判引发展开歧义</td></tr><tr><td>低重复通用长文本</td><td>接近零</td><td>匹配与校验开销纯增</td></tr><tr><td>高并发、符号表饱和</td><td>批内前缀复用提升</td><td>淘汰导致 TTFT 长尾</td></tr></tbody></table>\n<p>工程判断落在容量标定上：<span class=\"inline-math\">M</span> 必须与并发批大小、展开窗口 <span class=\"inline-math\">W</span> 联合标定，使符号表元数据占用与活跃 KV 之和稳定落在 B200/B300 档位的显存预算内；材料未给出任何吞吐与压缩率数字，因此上述比例只能作为部署前的测量清单，而非可直接引用的效率结论。</p>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-14\">十四 · 压缩上下文进入 kernel 时的形状问题</h3>\n<p>符号压缩把请求切成两股流：残差序列与符号表。到了算子层，这不是一个抽象的“更短的序列”，而是两个形状、生命周期、复用模式都不同的张量集合。残差是每请求私有的、按 token 顺序排列的激活；符号表是跨请求可复用的元数据，其条目在解码时被惰性展开成片段。工程上第一件事是决定这两股流各自以什么精度驻留、以什么精度参与矩阵乘。残差必须走完整的注意力与 MLP 路径，符号表则大部分时间只做查表与拼接，只有在展开窗口内才真正进入 QKV 投影。于是同一个 kernel launch 里可能出现两种数值路径：残差用 BF16 保动态范围，展开片段用 FP8 或 NVFP4 走权重侧，累加仍在 FP32。Blackwell 的 tcgen05 指令族对这种混合精度输入有原生支持，但前提是操作数布局符合 TMEM 的 tile 约定，否则会在 MMA 前插入额外的重排，把省下来的预填算力又吐回去。</p>\n<p>代价在这里非常具体：预填阶段每削减一个 token，就少一次 QK^T 与 PV 的乘加，但符号展开引入的 gather 与拼接会带来不规则的显存访问。若展开窗口边界不对齐到 128 字节，LDGSTS 的合并效率下降，带宽反而成为瓶颈。因此压缩层的输出应当以 tile 对齐的块为单位生成符号引用，而不是按任意字符边界切分——这与论文中“符号边界识别错误导致展开歧义”的失败模式是同一件事在硬件层的投影。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-15\">十五 · 数据类型选择：从 BF16 到 NVFP4 的逐级让渡</h3>\n<p>Blackwell 第五代 Tensor Core 的算力阶梯由输入精度决定，而推理的数值预算由误差容忍度决定。BF16 保留 8 位指数，动态范围与 FP32 同阶，适合残差与注意力 logits 这类跨度大的量；FP16 尾数多一位但指数窄，长上下文下 softmax 分母容易溢出，需要在线归一化配合。FP8 分 E4M3 与 E5M2 两支：E4M3 精度高、范围窄，用于权重与激活；E5M2 范围大、精度低，用于梯度类场景，推理中主要出现在对异常值敏感的归约路径。NVFP4 是 Blackwell 引入的 4 位微缩放格式，块内共享缩放因子，权重侧收益最大，但激活侧需要 per-block scale 的动态标定，否则展开片段的语义漂移会直接破坏 Expand(C(x))=x 的校验。</p>\n<p>把这条阶梯写成误差预算更清楚。设某一层输出为 y，量化引入的扰动为 δ，则相对误差可写成：</p>\n<div class=\"formula\">$$\\frac{\\|\\delta\\|_2}{\\|y\\|_2}\\;\\le\\;\\kappa(A)\\cdot\\frac{\\|\\Delta A\\|_2}{\\|A\\|_2}\\;+\\;\\frac{\\|\\Delta x\\|_2}{\\|x\\|_2}$$</div>\n<p>逐项解释：κ(A) 是权重矩阵的条件数，放大了权重扰动；第一项说明权重精度（NVFP4/FP8）的误差被条件数调制，第二项是激活精度（BF16/FP8）的直接贡献。对符号展开片段而言，x 是查表拼接出来的，其扰动不只来自量化，还来自符号表条目与原文的微小不一致——这正是还原校验要拦截的部分。工程判断是：权重可以激进到 NVFP4，激活至少保 FP8 E4M3，累加必须 FP32，且符号展开片段的激活精度不应低于残差，否则校验通过率会掉。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-16\">十六 · 累加精度与 tcgen05 的累加器位置</h3>\n<p>第五代 Tensor Core 把累加器从寄存器文件搬到了 TMEM（Tensor Memory）。tcgen05.mma 的输入取自 SMEM 或 TMEM，结果写回 TMEM，累加在 TMEM 内以 FP32 进行。这一步的意义不只是省寄存器：它让 2-SM MMA（两个 SM 协同执行一个更大的 MMA tile）成为可能，因为跨 SM 的累加器同步不再需要经过 register file 的反复搬运。对符号压缩而言，2-SM MMA 直接对应“展开窗口跨 tile 边界”的场景——一个符号引用展开出的片段可能跨越两个 128×256 的 tile，单 SM MMA 需要拆分并二次累加，2-SM 模式下一次完成，减少了部分和的舍入次数。</p>\n<p>累加精度的代价体现在吞吐与功耗的权衡上。FP32 累加器在 TMEM 中占用的位宽是 FP16 的两倍，TMEM 容量固定，于是同时驻留的累加 tile 数减半，流水深度受限。若为了堆吞吐把累加降到 FP16，长上下文下 K 维累加的舍入误差会累积，表现为 logits 尾部漂移，进而影响采样分布——这在代码补全这种要求确定性还原的场景里是不可接受的。因此合理配置是：主 MMA 走 FP32 累加，仅在符号表查表后的轻量投影上用低精度累加，并把这部分计算移出关键路径。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-17\">十七 · TMEM 容量与符号表驻留的联合标定</h3>\n<p>TMEM 是 Blackwell 上稀缺且不可换出的资源。每个 SM 的 TMEM 容量固定，tcgen05 的 tile 分配以列为单位。符号表本身不占 TMEM，但展开窗口内的活跃 KV 与累加器要争这块空间。设展开窗口长度为 W，头数为 H，头维为 d，则单层活跃 KV 的字节数为：</p>\n<div class=\"formula\">$$\\text{Bytes}_{\\text{KV}}=2\\cdot W\\cdot H\\cdot d\\cdot b,\\qquad b\\in\\{2,1,0.5\\}$$</div>\n<p>b 取 2 为 BF16、1 为 FP8、0.5 为 NVFP4。逐项看：系数 2 是 K 与 V 各一份；W 由符号展开策略决定，而非原始序列长度——这是压缩带来的直接杠杆；H·d 是模型固有；b 是量化档位。工程上 W 的上限不是拍脑袋定的，而是由 TMEM 剩余列数与并发批大小反推：批越大，每请求可分到的 TMEM 越少，W 必须相应收缩，否则 tcgen05 的 tile 分配失败会退化为低效路径。符号表容量上限 M 与 W 存在耦合——M 越大命中率越高、W 越小，但符号表元数据的查表延迟上升。二者需与并发批大小联合标定，这正是论文所说“符号表膨胀抵消压缩收益”的量化形态。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-18\">十八 · 一个仓库级补全的具体走位</h3>\n<p>设请求携带跨文件上下文，压缩层识别出重复的函数签名与注释模板，生成符号表条目并写入可缓存元数据。预填阶段只对残差与符号表计算注意力：残差走 BF16 激活、FP8 权重、FP32 累加的 tcgen05 路径；符号表条目在命中前缀缓存时直接复用，不重复预填。解码时遇到符号引用，从符号表惰性展开出片段，展开窗口 W 对齐到 128 字节，活跃 KV 以 FP8 驻留，仅覆盖当前窗口。若展开窗口跨越 tile 边界，2-SM MMA 一次完成累加，避免拆分带来的额外舍入与同步。</p>\n<p>这条路径的代价分布很清楚：预填 token 量下降带来算力与带宽节省，但展开时的 gather 与拼接把压力转移到显存访问的规则性上；NVFP4 权重降低权重带宽，但 per-block scale 的标定开销落在符号表管理侧；TMEM 的占用由 W 与批大小共同决定，W 超限则回退原文路径以保证 SLO。还原校验在输出前执行，失败即回退，这条兜底路径的延迟必须计入首 token 时延预算——代码补全场景对首 token 极敏感，校验开销不能放在关键路径的串行段上，而应与下一批的预填重叠。</p>\n<p>最终判断落在数值路径与符号路径的耦合点上：符号压缩削减的是 token 数与 KV 驻留，量化削减的是每字节的带宽与容量，两者在 Blackwell 上叠加的瓶颈不是算力而是 TMEM 与展开窗口的规则性。把 W 对齐到 tile、把符号表容量与并发批大小联合标定、把累加精度锁在 FP32，这三件事决定了压缩收益能否真正落到吞吐与延迟上，而不是被 gather 开销和校验回退吃掉。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-19\">十九 · 符号展开路径上的算子代价与数值边界</h3>\n<p>符号压缩把预填阶段的注意力计算对象从整段原文换成“残差序列 + 符号表”，但解码阶段的算子组合并未因此变轻，反而多出一条展开路径。惰性展开意味着每次遇到符号引用，都要把符号表条目重新物化为 token 片段，再送进注意力 kernel 参与当前窗口计算。这条路径上的核心 kernel 仍是 Blackwell 上的分块矩阵乘与 softmax 融合算子，数据类型则取决于部署侧的量化档位：BF16 作为还原校验与符号表元数据的默认精度，FP8 用于残差序列的预填矩阵乘，NVFP4 只在权重侧压缩时进入第五代 Tensor Core 的 tcgen05 指令流。展开片段一旦进入 KV，其驻留精度必须与残差序列一致，否则同一窗口内混合精度会破坏注意力分数的可比性。tcgen05 的 TMEM 累加器按块驻留，2-SM MMA 把一对 SM 的矩阵乘拼接成更大的 tile，这些特性让展开窗口的 tile 对齐变得敏感：符号边界若落在 tile 中间，展开片段就要跨 tile 重排，带来额外的 shared memory 搬运与同步开销。</p>\n<p>累加精度决定展开一致性校验能否成立。形式化约束要求 Expand(C(x))=x，而还原校验在数值层面只能做到近似相等，因为 FP8 或 NVFP4 的展开片段与原文在低位上并不逐位一致。设符号表条目 s 展开为片段 r，残差序列为 e，则压缩上下文的重建误差可写成</p>\n<div class=\"formula\">$$\\varepsilon=\\bigl\\|\\,\\mathrm{Dequant}\\bigl(\\mathrm{Expand}(s)\\bigr)+e-x\\,\\bigr\\|_2 \\le \\varepsilon_{q}+\\varepsilon_{b}$$</div>\n<p>其中 ε_q 来自展开片段的量化往返误差，ε_b 来自符号边界错位造成的片段截断或拼接。前者由数据类型位宽决定，后者由模式匹配阈值决定。工程上必须把 ε 与还原校验的判定阈值绑定：阈值过松则展开歧义被放过，阈值过紧则大量请求回退原文路径，压缩收益归零。TMEM 中的累加器若以 FP32 累加、FP8 输入，单次矩阵乘的误差可控，但展开窗口内多次符号引用叠加时误差会累积，这正是符号表容量上限 M 需要与批大小联合标定的原因——并发越高，单次展开窗口越长，ε_b 的尾部风险越大。</p>\n<p>系统代价集中在三处。其一是首 token 时延：展开路径在预填前插入符号识别与模式匹配，解码首个 token 前还要完成一次符号物化，这段开销直接计入 TTFT 预算，代码补全场景的低延迟要求使它成为硬约束，超限即回退原文。其二是显存与带宽：符号表作为元数据参与前缀缓存命中判断，其容量随仓库规模增长，若不做按复用频次的淘汰，符号表膨胀会吃掉 KV 节省下来的显存；展开窗口的 KV 虽只覆盖活跃片段，但窗口内 tile 对齐带来的重排会放大 shared memory 带宽占用。其三是功耗：2-SM MMA 与 tcgen05 的高吞吐建立在 tile 充分利用之上，展开片段跨 tile 重排造成的流水线气泡会拉低 Tensor Core 利用率，单位 token 的能耗随之上升。一个具体例子是仓库级代码补全请求携带跨文件上下文：函数签名与注释模板被抽象为符号，残差只保留本次编辑片段，预填 token 量下降，但解码时每个符号引用都要触发一次物化与 tile 重排，若符号边界恰好切在 2-SM MMA 的 tile 边界之外，单次展开的搬运开销可能抵消该符号带来的预填节省。因此该方案的适用边界是结构重复度高、符号边界与 tile 对齐良好的代码场景；跨语言或跨仓库的松散重复片段会让 ε_b 主导误差，还原校验频繁失败，回退路径反而成为常态。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>数值/算子约束</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>符号识别</td><td>模式匹配阈值人工设定</td><td>跨语言边界歧义</td><td>TTFT 增加，超限回退</td></tr><tr><td>展开物化</td><td>展开精度与残差一致</td><td>混合精度破坏注意力可比性</td><td>shared memory 搬运与同步</td></tr><tr><td>预填矩阵乘</td><td>FP8 输入、FP32 累加</td><td>多次引用误差累积</td><td>TMEM 累加器占用</td></tr><tr><td>tile 对齐</td><td>2-SM MMA tile 边界</td><td>符号边界跨 tile</td><td>流水线气泡、功耗上升</td></tr></tbody></table>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-20\">二十 · 显存账本的三层结构与符号压缩的落点</h3>\n<p>在 Blackwell 上做推理容量规划，第一件事是把显存拆成三本账：权重账、激活账、KV 账。权重账在模型加载后就固定，B200 单卡 HBM3e 容量按 192 GB 档位理解，权重占用由参数量与数值精度决定，NVFP4 权重每参数约半字节量级、FP8 约一字节，二者之差直接决定能否把整模型塞进单卡还是必须切分。激活账是预填阶段的临时峰值，随批内 token 数与序列长度平方项增长，属于可回收的瞬态开销。KV 账才是长上下文与仓库级复用场景里真正失控的一项：它随驻留 token 数线性增长，且在整个解码生命周期内常驻不释放。</p>\n<p>符号压缩的工程价值必须落在这三本账的哪一本上，才谈得上收益。它削减的是预填 token 量，因此同时作用于激活账（预填峰值下降）与 KV 账（驻留序列变短）。形式化定义给出压缩后的表示：</p>\n<div class=\"formula\">$$\\mathcal{C}(x)=\\{\\,(s_i,\\,r_i)\\,\\}_{i=1}^{n},\\quad \\mathrm{s.t.}\\;\\;\\mathrm{Expand}(\\mathcal{C}(x))=x,\\;\\;|\\mathcal{C}(x)|\\ll|x|$$</div>\n<p>这里的 <em>n</em> 是符号条目数，<em>r<sub>i</sub></em> 是残差片段。注意 |C(x)| 压缩的是“进入注意力的 token 数”，而不是“符号表本身的字节数”——符号表是元数据，占的是另一块小账，但它会随仓库规模增长，这一点在后文容量上限处展开。举例：一个跨文件补全请求携带 30k token 的仓库上下文，其中重复出现的函数签名与注释模板被抽成符号后，残差可能只剩本次编辑特有的片段，预填只对残差与符号表算注意力，KV 驻留随之从“整段 30k”降到“展开窗口”。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-21\">二十一 · KV 账的可复算预算：从字节公式到并发上限</h3>\n<p>KV 账的复算公式必须写死，否则容量规划只能靠拍脑袋。单 token 的 KV 字节数为：</p>\n<div class=\"formula\">$$\\text{Bytes}_{\\text{kv/token}}=2\\times L\\times H_{\\text{kv}}\\times d_{\\text{head}}\\times b_{\\text{elem}}$$</div>\n<p>其中 2 代表 K 与 V 两份，L 为层数，H<sub>kv</sub> 为 KV 头数（GQA/MQA 下远小于注意力头数），d<sub>head</sub> 为每头维度，b<sub>elem</sub> 为每元素字节数。FP8 KV 时 b<sub>elem</sub>=1，NVFP4 KV 时约半字节但需考虑缩放因子开销。以典型 70B 级 GQA 模型为例，L 取 80、H<sub>kv</sub> 取 8、d<sub>head</sub> 取 128，则单 token KV 约 160 KB（FP8）；若序列驻留 8k token，单请求即 1.3 GB 量级；并发 64 路就是 80 GB 以上——这已经吃掉 B200 192 GB 档位的一大块，还没算权重与激活。这个乘法链条就是容量规划的全部：并发数 × 平均驻留长度 × 单 token 字节 ≤ KV 预算上限。</p>\n<p>符号压缩改变的是“平均驻留长度”这一项。解码时按符号引用惰性展开，KV 仅对展开后的活跃窗口驻留，于是驻留长度从整段原文长度退化为展开窗口长度。代价是展开动作本身：每次遇到符号引用要查表、还原、重新计算该片段的 KV，这是一次额外的注意力计算与显存写入，落在首 token 时延与解码步时延上。因此预算里必须留出“展开开销”这一项，并设上限——超限回退原文路径，这是 SLO 约束下的硬开关，不是优化选项。</p>\n<table class=\"mini\"><thead><tr><th>账目</th><th>决定因素</th><th>符号压缩的作用</th><th>主要代价</th></tr></thead><tbody><tr><td>权重</td><td>参数量 × 精度</td><td>无</td><td>加载与常驻，不可回收</td></tr><tr><td>激活</td><td>批内 token 数、序列长度</td><td>预填 token 减少，峰值下降</td><td>瞬态，可回收</td></tr><tr><td>KV</td><td>并发 × 驻留长度 × 单 token 字节</td><td>驻留退化为展开窗口</td><td>展开计算与写回</td></tr><tr><td>符号表</td><td>条目数 × 条目字节</td><td>新增元数据账</td><td>查表、淘汰、膨胀监控</td></tr></tbody></table>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-22\">二十二 · 分页与复用：符号表作为前缀缓存元数据</h3>\n<p>KV 分页（paged KV）把 KV 切成固定大小的 block，按需分配、按引用计数共享，这是连续批处理与前缀缓存共同的底座。前缀缓存命中时，相同前缀的 block 被多请求共享，省掉重复预填。符号压缩与这套机制正交：它不改变 block 的物理布局，而是改变“什么内容需要被预填”。关键在于符号表本身可以作为可缓存元数据参与命中判断——跨请求若命中同一符号表，则直接复用符号表而非原文，仓库级复用场景下这等于把“重复预填”从 token 级降到符号级。</p>\n<p>复用带来的收益要按带宽算，而不是按容量算。前缀缓存命中省下的是预填阶段的 HBM 读写与 MMA 计算；符号表命中省下的是符号识别与模式匹配的扫描开销。二者叠加时，预填路径上真正跑的是残差序列与符号表引用，注意力计算的 token 数下降，HBM3e 带宽压力随之下降。但要注意一个反直觉的点：符号表命中率越高，单次请求的预填越短，批内各请求的预填长度差异越大，连续批处理的调度器反而更难把预填与解码拼成均衡的批次——这是复用带来的调度代价，需要在批调度策略里显式处理，而不是假设复用总是免费。</p>\n<p>具体例子：agent 工具调用循环中，同一仓库的多轮请求反复携带相同的工具定义与文件头注释。第一轮生成符号表并写入缓存，后续轮次命中符号表，预填只处理本轮新增的编辑片段。若符号表未命中，则退化为普通前缀缓存路径，二者不冲突。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-23\">二十三 · 压缩、卸载与带宽瓶颈的真实位置</h3>\n<p>KV 压缩有三条常见路线：量化（FP8/NVFP4）、结构压缩（跨层共享、低秩）、以及本文的符号压缩。三者的作用点不同：量化降低 b<sub>elem</sub>，结构压缩降低有效头数或维度，符号压缩降低驻留 token 数。它们可以叠加，但叠加时误差与开销也叠加——量化引入数值误差，符号压缩引入展开歧义，二者都需要校验兜底。工程上应先量化再符号化：量化是逐元素的确定性变换，符号化是规则驱动的结构变换，后者失败时回退原文路径的成本更高。</p>\n<p>卸载（offload）把冷 KV block 搬到主机内存或远端存储，用 PCIe/NVLink 换 HBM 容量。卸载的瓶颈从来不是容量，而是带宽：解码每一步都要把被引用的 KV 拉回 HBM，若命中率不高，搬运延迟直接压垮 TPOT。符号压缩在这里的角色是“减少需要卸载的量”——驻留窗口变短后，冷数据比例下降，卸载频率下降。但符号展开本身要读符号表，符号表若放在主机侧，展开就变成一次跨总线读，这条路径的延迟必须计入首 token 预算。</p>\n<p>带宽瓶颈的真实位置需要分清：预填阶段是计算密集偏带宽，解码阶段是带宽密集偏延迟。Blackwell 的 tcgen05 与 TMEM 把 MMA 的吞吐推高，2-SM MMA 让大 tile 的利用率上升，于是解码阶段的瓶颈更彻底地落在 HBM 读写 KV 上。符号压缩削减的是 KV 读写量，因此它的收益在解码阶段比在预填阶段更直接；但它的开销（展开计算）也落在解码步里，二者相抵后的净值必须在目标 SLO 下实测，材料未给出任何定量数字，不能预设净收益为正。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-24\">二十四 · 符号表容量上限与膨胀的联合标定</h3>\n<p>符号表不是免费的。设容量上限为 M，条目按复用频次淘汰低频符号，则符号表字节数上界为 M × 条目平均字节。M 的标定必须与并发批大小联合做：并发越高，同时驻留的符号表副本越多（若不做跨请求共享），元数据账就越重。膨胀速率是必须监控的指标——仓库级上下文中，符号边界识别错误会产生大量低复用、高歧义的符号，这些符号既占表又不省 KV，直接抵消收益。</p>\n<p>还原校验是兜底机制：输出前校验 Expand(C(x))=x，失败则回退原文路径。这条规则把符号压缩从“有损压缩”变成“可核验的无损变换”，代价是校验本身的算力与延迟。校验粒度需要工程判断：逐符号校验精确但慢，按请求整体校验快但定位失败点困难。合理做法是逐符号校验加失败计数，失败率超阈值时自动降低符号化激进程度（提高模式匹配阈值），把系统推向保守路径。</p>\n<p>伪代码思路：预填前扫描残差与候选符号，若符号表条目数将超 M，则按频次淘汰；解码遇符号引用时查表展开并校验，校验失败则标记该符号为不可用并回退原文。监控三件事：还原失败率、符号表膨胀速率、预填 token 节省比例。三者任一越界，压缩层降级。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-25\">二十五 · 与量化、分离式预填叠加时的账本重算</h3>\n<p>符号压缩与 NVFP4/FP8 量化叠加时，KV 账要重算：量化把 b<sub>elem</sub> 降下来，符号压缩把驻留长度降下来，二者相乘才是最终 KV 占用。但量化后的 KV 在展开时需要反量化再计算，展开路径的算力开销上升；若展开窗口小，这笔开销可摊薄，若展开频繁，开销累积。与分离式预填/解码拓扑叠加时，符号识别与符号表生成应放在预填节点侧，解码节点只做查表展开，这样符号表作为元数据在预填与解码之间传递，传输量远小于原文，正好利用 NVLink 5 的高带宽做元数据同步而非 KV 同步。</p>\n<p>最终判断落在一条工程规则上：符号压缩的容量收益只有在“结构重复度高、符号表命中率高、展开窗口可控”三个条件同时成立时才为正。代码补全与仓库级复用满足前两条，第三条靠展开窗口上限与回退路径保证。通用长文本推理不满足第一条，规则维护成本会吞掉收益。因此在这套显存账本里，符号压缩应被当作 KV 账的一个可选折扣项，而不是默认开启的全局优化——它的开关阈值必须由还原失败率与符号表膨胀速率两个监控量驱动，而不是由压缩率这一个好看的数字驱动。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-26\">二十六 · 符号压缩的显存账本边界：驻留窗口、符号表开销与回退代价</h3>\n<p>把符号压缩放进显存账本时，关键不是“压缩率”，而是<strong>驻留对象从序列长度切换为展开窗口</strong>。设原始序列长 <em>L</em>、每 token 每层 KV 字节为 <em>k</em>、层数 <em>N</em>、并发批 <em>B</em>，则未压缩驻留为 <em>B·L·N·k</em>；压缩后活跃 KV 只覆盖当前展开窗口 <em>W</em>，驻留近似 <em>B·W·N·k</em> 加上符号表元数据 <em>M·e</em>（<em>e</em> 为单条符号条目字节）。账本成立的前提是 <em>W ≪ L</em> 且 <em>M·e</em> 不随并发线性膨胀——一旦符号表按请求各存一份，元数据项就会在批内叠加，抵消掉窗口收益。这也是该方案与分页 KV、前缀缓存的分界线：后者压缩的是块粒度与跨请求复用，前者压缩的是“同一请求内部的重复结构”，两者叠加时须分别核算，不能把符号表命中率当成 KV 命中率。</p>\n<div class=\"formula\">$$ \\text{Resident} \\approx B\\cdot W\\cdot N\\cdot k \\;+\\; \\alpha\\cdot M\\cdot e,\\qquad \\text{收益条件：}\\; W\\cdot k \\;&lt;\\; L\\cdot k \\;-\\; \\frac{\\alpha M e}{B N} $$</div>\n<p>失效条件集中在三处。其一是<strong>符号边界识别错误</strong>：规则由人工设定、不依赖训练，跨语言与跨仓库时模式匹配阈值稍有偏移就会切出歧义片段，展开结果与原序列不等，只能靠 <em>Expand(C(x))=x</em> 的还原校验兜底并回退原文路径——回退意味着该请求的预填 token 量与 KV 驻留回到未压缩水平，等于白付一次符号识别与校验的算力。其二是<strong>符号表膨胀</strong>：容量上限 <em>M</em> 触发按复用频次淘汰低频符号，淘汰后再次命中即需重新识别，形成“识别—淘汰—再识别”的抖动，膨胀速率监控必须与并发批大小联合标定。其三是<strong>展开延迟挤占首 token 预算</strong>：代码补全要求低延迟，惰性展开在解码每一步都要取符号并拼接，这段开销不进预填却进 TTFT，超限即回退，SLO 越紧、可用压缩窗口越窄。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随什么增长</th><th>工程约束</th></tr></thead><tbody><tr><td>活跃 KV</td><td>展开窗口 W、批 B、层 N</td><td>W 上限由 SLO 与展开延迟反推</td></tr><tr><td>符号表元数据</td><td>符号数 M、是否按请求复制</td><td>M 上限 + 频次淘汰，尽量跨请求共享</td></tr><tr><td>回退路径</td><td>识别失败率 × 原序列长度</td><td>失败率须监控，回退预算计入容量规划</td></tr></tbody></table>\n<p>因此这套方案适合结构重复度高、跨文件模板密集的仓库级代码场景，而不适合重复度低、符号边界模糊的通用长文本。材料未给出任何吞吐、延迟或压缩率数字，容量规划只能按上式自行标定：先在目标硬件档位上测出 <em>W</em> 与展开延迟的关系、<em>M</em> 与命中率的关系，再把回退率作为独立项计入显存与算力预算，而不是把符号压缩当作免费的 KV 折扣。</p>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-27\">二十七 · 符号压缩上下文进入调度器的形态变化</h3>\n<p>符号压缩对调度的影响不是\"少算几个 token\"，而是把一条请求拆成了两种生命周期不同的对象：残差序列与符号表。前者随请求生灭，后者跨请求驻留、可被前缀缓存命中、也可被容量上限淘汰。连续批处理（continuous batching）的调度器原本以\"序列\"为最小调度单元，现在必须同时跟踪符号引用计数：一个符号被多少个活跃请求引用、展开窗口落在哪一段、展开后的活跃 KV 何时释放。这一步不做好，压缩层省下的预填算力会被调度抖动吃掉。</p>\n<p>具体机制上，压缩层在预填前完成符号识别与替换，调度器看到的输入是残差 token 流加一张符号表句柄。预填阶段只对残差与符号表计算注意力，KV 驻留因此不再随原始序列长度线性增长，而随\"残差长度 + 当前展开窗口\"增长。用公式表达调度侧的显存约束：</p>\n<div class=\"formula\">$$B_{\\text{batch}} = \\sum_{j \\in \\text{batch}} \\bigl(|\\text{res}_j| + W_j\\bigr)\\cdot d_{\\text{kv}} + M\\cdot d_{\\text{sym}} \\le B_{\\text{cap}}$$</div>\n<p>其中 \\(W_j\\) 是请求 j 的展开窗口长度，\\(M\\) 是符号表容量上限，\\(d_{\\text{sym}}\\) 是符号表每条目的元数据开销。这个不等式是连续批处理准入判断的新形式：批大小不再由最长序列决定，而由残差总量、展开窗口与符号表驻留三者共同约束。工程代价直接体现在准入延迟上——每来一个新请求，调度器要额外做一次符号引用计数更新与容量检查，这段开销必须压在微秒级，否则高并发下准入本身成为瓶颈。</p>\n<p>例子：仓库级代码补全中，一次请求携带跨文件上下文，压缩层把重复出现的函数签名与注释模板抽为符号，残差只保留本次编辑片段。若同一符号表已被前序请求写入前缀缓存，新请求的预填 token 量骤降，调度器可把腾出的 KV 预算分配给更多并发请求；反之若符号表未命中，则需先完成符号表构建，这段构建延迟必须计入首 token 时延（TTFT）预算。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-28\">二十八 · Chunked prefill 与展开窗口的粒度对齐</h3>\n<p>Chunked prefill 把长预填切成若干块与解码步交错执行，目的是压住解码请求的尾延迟不被长预填饿死。符号压缩引入了一个新约束：切块边界不能落在符号引用中间，否则展开时要么跨块拼接符号表、要么触发一次额外的还原校验。可行的做法是以\"残差块 + 完整符号引用\"为切分单位，块大小按展开窗口 \\(W\\) 的整数倍对齐，使每个 chunk 的注意力计算范围自洽。</p>\n<p>伪代码思路：调度器维护一个待预填队列，每轮取若干 chunk 组成 prefill batch，同时从解码队列取若干步组成 decode batch，二者拼成一次前向。符号引用的展开在 chunk 进入注意力之前完成，展开结果只在该 chunk 的生命周期内驻留 KV。这样 chunked prefill 的块粒度与符号展开窗口天然耦合：块越大，单次展开的 KV 峰值越高但调度开销越低；块越小，尾延迟越平滑但符号表查询次数上升。</p>\n<p>代价分析：chunked prefill 的收益是解码步的 inter-token latency（ITL）更稳定，代价是预填总算力略增（块边界处的注意力重复计算）与调度复杂度上升。符号压缩把预填 token 量降下来之后，chunk 数减少，块边界重复计算的绝对量也随之下降，两者叠加对 TTFT 有利；但展开窗口若设置过大，单 chunk 的 KV 峰值会顶到显存上限，迫使调度器缩小并发批，反而拉低吞吐。因此展开窗口 \\(W\\) 必须与 chunk 大小、并发批上限联合标定，不能单独调。</p>\n<p>例子：一个 agent 循环中，工具调用返回的代码片段被符号化后进入下一轮预填，若 chunk 边界恰好切在符号引用处，展开逻辑需回退到原文路径重算该 chunk，这次回退直接体现为一次 TTFT 抖动。把切分单位改为\"完整符号引用\"后，回退率下降，尾延迟分布收敛。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-29\">二十九 · 优先级、抢占与符号表的引用计数</h3>\n<p>多租户或 agent 场景下，请求优先级差异明显：交互式补全要求低 TTFT，后台批处理可容忍高吞吐低优先级。抢占（preemption）在连续批处理中通常以\"换出 KV 到主机内存再换入\"实现，符号压缩改变了换出成本的结构——残差 KV 仍需换出，但符号表是共享元数据，不应随单个请求换出，否则引用它的其他请求全部失效。</p>\n<p>机制上，符号表按引用计数管理：计数归零才允许淘汰，淘汰策略按复用频次排序，容量上限 \\(M\\) 触发时优先淘汰低频符号。抢占一个请求时，调度器只换出其残差 KV 与展开窗口 KV，符号表句柄保留在元数据池中；若该请求被重新调度，展开窗口按需重建，符号表直接复用。这把抢占的换出带宽从\"整段序列 KV\"降到\"残差 + 窗口 KV\"，换出/换入延迟随之下降。</p>\n<p>代价：引用计数本身是调度器的一把锁，高并发下计数更新会成为竞争点，需要用分片计数或批量更新摊薄。另一个代价是符号表驻留占用显存，\\(M\\cdot d_{\\text{sym}}\\) 这部分不随请求释放，等于给调度器加了一笔固定显存税；容量上限设得过大，符号表膨胀会抵消压缩收益，设得过小则命中率下降、预填节省打折。这个权衡没有解析解，只能按仓库重复度与并发规模实测标定。</p>\n<p>例子：NVL72 机架内多个推理实例共享同一仓库上下文，若各实例独立维护符号表，跨实例复用率为零；把符号表下沉为机架级共享元数据（经 NVLink 5 域内访问），引用计数跨实例聚合，淘汰决策全局一致，预填节省才能在机架尺度上兑现。这一步与 KV 前缀缓存的跨实例共享是同一类工程问题。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-30\">三十 · 分离式预填/解码下的符号表放置</h3>\n<p>分离式（disaggregated）预填/解码把预填节点与解码节点拆开，KV 经高速互联从预填侧传到解码侧。符号压缩与这个拓扑正交，但放置策略需要重新设计：符号表应在预填侧构建并驻留，因为符号识别与模式匹配发生在预填之前；解码侧的惰性展开需要按符号引用向预填侧取符号表条目，或由预填侧在传输 KV 时一并下发被引用的符号条目。</p>\n<p>传输代价是这里的核心：分离式拓扑下 KV 传输量原本正比于序列长度，符号压缩后传输量变为\"残差 KV + 展开窗口 KV + 符号条目\"。符号条目若被多个解码请求共享，可只传一次并在解码侧缓存；但解码侧的符号表缓存同样受容量约束，缓存未命中时需回源预填侧，这次回源是一次跨节点往返，直接落在 ITL 上。工程判断是：把高频符号条目预置到解码侧常驻缓存，低频条目按需回源，回源延迟设上限，超限则回退原文路径以保证 SLO。</p>\n<p>公式上，解码侧单步的额外延迟可写成：</p>\n<div class=\"formula\">$$L_{\\text{step}} = L_{\\text{attn}} + h\\cdot L_{\\text{expand}} + (1-h)\\cdot L_{\\text{fetch}}$$</div>\n<p>其中 \\(h\\) 是符号条目在解码侧缓存命中率，\\(L_{\\text{fetch}}\\) 是回源往返延迟。\\(h\\) 越高，展开开销越接近纯本地计算；\\(h\\) 低时回源延迟主导，此时符号压缩的净收益可能为负。这解释了为什么该方法更适合结构重复度高的代码场景——重复度高则 \\(h\\) 高，回源少。</p>\n<p>例子：GB200 NVL72 内预填与解码分处不同 GPU，符号表在预填侧构建后，高频函数签名条目随 KV 传输一并下发并在解码侧常驻，低频注释模板条目按需回源。若某仓库跨文件重复片段比例高，常驻缓存命中率高，解码侧几乎不触发回源，ITL 稳定；若仓库结构松散，回源频繁，需调低展开窗口或直接回退原文。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-31\">三十一 · 尾延迟的压缩路径与回退路径</h3>\n<p>尾延迟（P99 TTFT / P99 ITL）是 SLO 的真正约束，平均值好看不代表达标。符号压缩对尾延迟的影响是双面的：命中路径上预填 token 量下降、KV 驻留下降，尾延迟改善；未命中或展开歧义路径上，还原校验失败触发回退原文，这条路径的延迟高于不压缩的基线，直接把尾部拉长。因此调度器必须把回退率作为一等指标监控，并对回退设预算。</p>\n<p>机制上，输出前的还原校验 \\(\\mathrm{Expand}(\\mathcal{C}(x))=x\\) 是强制步骤，校验失败即回退。回退的成本是\"丢弃已展开结果 + 重算原文预填\"，在长上下文下这是一次显著的算力回补。控制手段有三：其一，符号边界识别阈值调保守，宁可少压缩不可错压缩；其二，回退请求降优先级并单独排队，避免污染交互式请求的尾延迟；其三，对回退率高的仓库临时关闭压缩路径，退回纯前缀缓存方案。</p>\n<p>代价与取舍：压缩率与回退率是一对反向指标。阈值放宽提升压缩率、降低平均预填量，但符号边界误判增多、回退率上升、尾延迟恶化；阈值收紧则相反。这个取舍应按 SLO 反解：给定 P99 TTFT 上限，先测回退率随阈值的变化曲线，取满足尾延迟约束的最大压缩率。吞吐侧的取舍同理——压缩率高则单卡可承载并发上升，但回退请求的重算算力会挤占正常请求的算力配额，净吞吐未必线性提升。</p>\n<p>例子：代码补全场景要求低延迟，符号展开开销必须纳入 TTFT 预算。若某次请求的展开窗口过大导致展开延迟超限，调度器应即时回退原文路径而非硬扛，这次回退虽增加单请求算力，但保住了 P99 达标；反之若为省算力硬扛超限展开，尾部抖动会传导到整个批，拖垮同批其他请求的 ITL。</p>\n<p>工程判断落在具体机制上：把符号表容量上限 \\(M\\)、展开窗口 \\(W\\)、回退率阈值三者做成联动配置，由调度器在准入时按当前批的残差总量与符号表驻留实时反解可用并发，而不是静态设定批大小。压缩层省下的预填算力只有在这套联动配置下才能转化为吞吐，否则只是把显存压力从 KV 转移到了符号表与调度开销上。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-32\">三十二 · 符号压缩在调度层的失效边界与批处理代价</h3>\n<p>符号压缩把预填 token 量与 KV 驻留从“序列长度”解耦到“残差长度 + 展开窗口”，这对连续批处理是结构性利好：批内各请求的残差长度方差远小于原文长度方差，chunked prefill 的切块粒度因此更容易对齐，抢占时被换出的 KV 也只剩活跃展开窗口。但它同时引入一个新的调度维度——符号表命中状态。设批内请求集合为 <span class=\"formula\">$$B$$</span>，可调度性不再只由 token 预算决定，而由 <span class=\"formula\">$$\\sum_{r\\in B}\\big(|x_r^{\\text{res}}|+|W_r|\\big)\\le T_{\\text{budget}},\\quad \\sum_{r\\in B}\\big(|T_r|+|W_r|\\big)\\le M_{\\text{KV}}$$</span> 共同约束，其中 <span class=\"formula\">$$|T_r|$$</span> 为符号表驻留、<span class=\"formula\">$$|W_r|$$</span> 为展开窗口。符号表未命中前缀缓存的请求必须先做符号识别与模式匹配，这段“压缩前置”落在首 token 时延预算里，且无法与解码批重叠——它是纯串行开销，优先级调度必须把它当作不可抢占的临界区处理，否则高优先级请求会在压缩层排队。</p>\n<p>失效条件集中在两处。其一是符号边界识别错误：规则匹配在跨语言、跨仓库命名风格下产生歧义，还原校验 <span class=\"formula\">$$\\mathrm{Expand}(\\mathcal{C}(x))=x$$</span> 失败即触发回退原文路径，此时该请求的预填成本瞬间回到未压缩水平，而批调度器此前已按压缩后的预算分配了 KV 与算力，回退会造成批内显存超配与 chunk 重排。其二是符号表膨胀：容量上限 <span class=\"formula\">$$M$$</span> 触发按复用频次淘汰低频符号后，被淘汰符号在后续解码中重新展开为原文，活跃窗口变大，KV 驻留回升。两种失效都不是渐变的，而是阶跃式的，因此监控必须以还原失败率与符号表膨胀速率作为抢占信号，而非仅看 GPU 利用率。</p>\n<table class=\"mini\"><thead><tr><th>调度决策</th><th>压缩带来的变化</th><th>系统代价</th></tr></thead><tbody><tr><td>连续批处理组批</td><td>残差长度方差小，批更易填满</td><td>符号表驻留计入显存预算</td></tr><tr><td>chunked prefill 切块</td><td>切块按残差计，块数下降</td><td>压缩前置串行段不可切分</td></tr><tr><td>抢占与换出</td><td>换出量随展开窗口而非原文</td><td>回退原文时需重建整段 KV</td></tr><tr><td>分离式预填/解码</td><td>预填节点只算残差与符号表</td><td>符号表需跨节点传输与一致性校验</td></tr></tbody></table>\n<p>在分离式预填/解码拓扑下，符号表作为元数据随请求从预填节点传到解码节点，跨节点传输量远小于原文 KV，这是压缩与 PD 分离正交叠加的真实收益点；但解码节点的惰性展开是逐符号触发的，展开窗口的 KV 写入呈突发性，与解码批的稳定带宽需求叠加后容易在 NVLink 5 链路上形成短时拥塞。尾延迟的压法因此不是加大批，而是给展开窗口设硬上限并对超限请求降级为原文路径，把 p99 的抖动源从“符号表命中不确定性”收敛为可预算的固定开销。对代码补全这类首 token 敏感场景，压缩前置与展开开销必须显式计入 SLO 预算，规则维护成本高的仓库应直接关闭压缩层，让前缀缓存独自承担复用。</p>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-33\">三十三 · 切分维度与符号压缩的耦合点</h3>\n<p>在 Blackwell 拓扑上谈并行，先要把切分维度与压缩层的交互关系摆清楚。张量并行（TP）切的是单层内的权重矩阵与注意力头，每个 rank 持有部分列或行，前向需要 All-Reduce 或 Reduce-Scatter 汇总部分和；专家并行（EP）切的是 MoE 的专家集合，token 需按路由结果做 All-to-All 重排；流水并行（PP）切的是层，激活沿 stage 边界以点对点传递；数据并行（DP）切的是批，梯度不参与推理，但 KV 与前缀缓存按副本各自持有。符号压缩改变的是进入预填的 token 流长度：残差序列变短、符号表作为元数据单独驻留。这意味着 TP 的 All-Reduce 消息量随每层激活的 token 数线性下降，而 EP 的 All-to-All 却因为符号表需要跨 rank 共享而新增一条元数据通路。工程判断是：压缩收益在 TP 主导的密集模型上直接体现为集合通信量下降，在 EP 主导的 MoE 上则要先解决符号表的分片归属，否则 All-to-All 的 dispatch 阶段仍按展开后的 token 计费。</p>\n<p>形式化地，设单层激活张量为 $A\\in\\mathbb{R}^{b\\times s\\times h}$，TP 组规模为 $G_t$，则一次 All-Ring All-Reduce 的单 rank 通信量为</p>\n<div class=\"formula\">$$V_{\\text{AR}} \\approx 2\\cdot\\frac{G_t-1}{G_t}\\cdot b\\cdot s\\cdot h\\cdot \\text{sizeof(dtype)}$$</div>\n<p>符号压缩把 $s$ 替换为残差长度 $s_r$ 与符号表展开窗口 $s_w$ 的较小者，$V_{\\text{AR}}$ 随之下降；但若符号表本身需在 TP 组内广播以支持惰性展开，则新增 $V_{\\text{sym}}=|\\mathcal{C}(x)|\\cdot h\\cdot\\text{sizeof(dtype)}$ 的元数据同步。当 $|\\mathcal{C}(x)|$ 接近 $s$ 时，这笔账会反噬。以仓库级代码补全为例：跨文件重复的函数签名被抽象为符号后，残差序列只剩本次编辑片段，单层激活的 $s$ 从数千 token 降到数百，TP=8 下每层 All-Reduce 的字节数按比例收缩，NVLink 5 上的集合通信从带宽受限退回延迟受限区间——此时瓶颈从链路搬到 kernel launch 与同步开销。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-34\">三十四 · NVLink 5 与 NVSwitch：带宽账与拓扑选择</h3>\n<p>Blackwell 世代的 NVL72 机柜以 NVLink 5 与 NVSwitch 构成全互联域，单 GPU 对外链路带宽远高于 PCIe，使得 TP 组可以跨 8 卡乃至更大规模而不至于被链路压死。但带宽高不等于通信免费：All-Reduce 的实际耗时由链路带宽、协议开销与同步点三者共同决定。对 TP 而言，每层两次集合通信（前向一次、反向不涉及）串在关键路径上，层数越多，通信与计算的 overlap 窗口越窄。符号压缩缩短了每层消息，却也让单次通信落入延迟主导区，此时 NVSwitch 的交换延迟与 NCCL 的算法选择（Ring 还是 Tree）比峰值带宽更决定端到端时延。</p>\n<p>代价侧要盯住三个量：单次 All-Reduce 的固定开销（与消息大小弱相关）、每 token 的通信字节数、以及通信与计算的 overlap 比例。设单层计算时间为 $T_c$、通信时间为 $T_m$，则 TP 的并行效率近似为</p>\n<div class=\"formula\">$$\\eta_{\\text{TP}} \\approx \\frac{T_c}{T_c + T_m\\cdot(1-\\alpha)}$$</div>\n<p>其中 $\\alpha$ 为 overlap 比例。符号压缩降低 $T_m$ 中与 $s$ 成正比的部分，但抬高了固定开销占比，$\\alpha$ 若不随消息变小而提升，$\\eta_{\\text{TP}}$ 的改善会被稀释。具体例子：一个 70B 级密集模型在 TP=8、NVLink 5 域内运行时，若残差序列使单层消息从 MB 级降到百 KB 级，Ring 算法的步进延迟成为主导，此时改用 Tree 或把 TP 组收缩到 4 卡、以 DP 补足吞吐，往往比硬撑 8 卡 TP 更划算。这是压缩层带来的拓扑再平衡问题，材料未给出档位数据，需按实际链路时延标定。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-35\">三十五 · All-to-All 与 EP：符号表归属决定瓶颈位置</h3>\n<p>EP 的通信形态与 TP 不同：All-to-All 的 dispatch 与 combine 两段，消息量正比于被路由的 token 数乘以隐藏维。符号压缩若只压缩残差，展开发生在解码侧，则 dispatch 阶段仍要按展开后的 token 计费，EP 的 All-to-All 成为未被压缩触及的瓶颈。反之，若把符号引用本身作为路由单元下发，各 rank 在本地展开后再算专家，则 dispatch 消息量按符号粒度下降，但 combine 阶段需保证同一符号在不同 rank 展开一致，否则归约出错。工程上可行的折中是：符号表按专家亲和性分片，每个 rank 只持有本 rank 专家可能命中的符号子集，dispatch 传符号 ID 与残差，combine 传部分和。代价是符号表分片带来额外驻留，且分片边界与路由分布耦合，负载倾斜时某 rank 的符号表膨胀。</p>\n<p>瓶颈判据可以写成：设 EP 组规模 $G_e$、每 token 路由到 $k$ 个专家，则单 token 的 All-to-All 字节数为 $2k\\cdot h\\cdot\\text{sizeof(dtype)}$，与序列长度无关而与 batch 内 token 数成正比。符号压缩削减的是 batch 内有效 token 数，因此 EP 的通信收益取决于压缩后仍需要路由的 token 比例 $\\rho$：</p>\n<div class=\"formula\">$$V_{\\text{A2A}} \\approx \\rho\\cdot b\\cdot s\\cdot 2k\\cdot h\\cdot\\text{sizeof(dtype)}$$</div>\n<p>$\\rho$ 高（残差占比大、符号命中少）时 EP 通信几乎不受压缩影响，瓶颈仍在 All-to-All；$\\rho$ 低时通信让位于符号表同步与展开一致性校验。具体例子：仓库级上下文里大量重复的 import 块与注释模板被符号化后，$\\rho$ 显著下降，MoE 的 dispatch 消息量随之收缩，但每个 rank 需在展开前校验符号边界，这笔校验算力落在解码关键路径上，与 All-to-All 的延迟叠加而非重叠。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-36\">三十六 · PP 与 DP：边界传递与副本冗余</h3>\n<p>PP 的通信量小但敏感：stage 边界只传激活，消息量正比于 micro-batch 大小与隐藏维，符号压缩缩短序列后，边界消息同步变小，PP 的 bubble 占比反而上升——因为每 stage 的计算时间缩短，而 stage 间同步的固定延迟不变。PP 的 bubble 比例为</p>\n<div class=\"formula\">$$\\text{bubble} \\approx \\frac{G_p-1}{G_p}\\cdot\\frac{T_{\\text{stage\\_comm}}}{T_{\\text{stage\\_compute}}+T_{\\text{stage\\_comm}}}$$</div>\n<p>压缩让 $T_{\\text{stage\\_compute}}$ 下降，bubble 比例上升，工程上需增加 micro-batch 数或改用交错调度填补。DP 侧的问题不同：每个副本独立持有符号表与前缀缓存，仓库级复用时同一符号表在 $G_d$ 个副本上重复驻留，显存开销乘以副本数。符号表容量上限 $M$ 与 DP 规模的乘积决定元数据总驻留，若 $M$ 按单副本标定而未随 DP 放大，跨请求复用率下降；若放大 $M$，显存又被元数据挤占。这是压缩层与 DP 的显存账，材料未给容量数字，只能定性判断：符号表应按复用频次做跨副本一致性哈希，而非每副本独立淘汰。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-37\">三十七 · NIXL 传输与分离式拓扑下的通信路径</h3>\n<p>分离式预填/解码把预填与解码拆到不同 GPU 池，KV 需从预填池传到解码池，NIXL 承担这段点对点传输。符号压缩在此拓扑下的作用有两面：预填只算残差与符号表，产出的 KV 只覆盖活跃展开窗口，传输量按窗口而非整段序列计；但解码侧惰性展开需要符号表随 KV 一同传输，否则解码 rank 无法还原。于是 NIXL 的传输对象从纯 KV 变为 KV 加符号表元数据，后者是低频大块、前者是高频小块，传输模式从流式变为混合。代价判断：当展开窗口远小于原序列时，KV 传输量下降主导收益；当符号表体积接近 KV 体积时，元数据传输抵消节省，此时应把符号表预置到解码池的常驻缓存而非每请求传输。</p>\n<p>通信何时成为瓶颈，可以用一个粗判据收束：设单请求的计算时间为 $T_{\\text{comp}}$、通信时间为 $T_{\\text{comm}}$（含集合通信与 NIXL 传输），当 $T_{\\text{comm}}/T_{\\text{comp}}&gt;\\gamma$（$\\gamma$ 由 SLO 的尾延迟预算反推）时，通信进入瓶颈区。符号压缩降低 $T_{\\text{comp}}$ 中的预填部分与 $T_{\\text{comm}}$ 中的 KV 传输部分，但对集合通信的固定开销与符号表同步无能为力，因此压缩后系统更容易落入通信瓶颈区——这不是压缩的失败，而是拓扑需要随压缩比重新标定：TP 组收缩、EP 分片细化、PP 增加 micro-batch、NIXL 路径上符号表常驻化，四者按实测的 $T_{\\text{comm}}/T_{\\text{comp}}$ 逐项调整，而非沿用未压缩时的并行配置。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-38\">三十八 · 符号表元数据在 TP/EP/PP/DP 切分下的通信边界</h3>\n\n<p>符号压缩把预填 token 量压到残差序列加符号表，这一步直接改变了并行拓扑的通信画像。TP 的 All-Reduce 规模正比于每层激活的隐藏维切片，与序列长度无关，因此压缩对 TP 通信量的削减几乎为零；EP 的 All-to-All 规模正比于每 token 的路由专家数，压缩削减的是 token 数，收益接近线性；PP 的激活传递量正比于 micro-batch 的 token 数乘以隐藏维，压缩同样线性受益；DP 的梯度 All-Reduce 在推理侧不存在，取而代之的是符号表元数据的跨副本同步。判断通信是否成为瓶颈，要看压缩后剩余的计算时间是否已经短到被固定通信开销淹没。设单层计算时间为 $t_{\\text{comp}}$、通信时间为 $t_{\\text{comm}}$，压缩把计算侧缩减为 $\\alpha t_{\\text{comp}}$（$\\alpha&lt;1$），而 TP 的 All-Reduce 时间基本不变，则计算通信比从 $t_{\\text{comp}}/t_{\\text{comm}}$ 退化为 $\\alpha t_{\\text{comp}}/t_{\\text{comm}}$。当 $\\alpha$ 小到使该比值低于 NVLink 5 域内可隐藏的阈值，TP 组内就会从计算受限转为通信受限——这正是符号压缩在 TP 度较高时的第一个失效条件。</p>\n\n<p>符号表本身是跨请求共享的元数据，它的放置位置决定了一次命中是省下预填还是引入一次远程拉取。仓库级复用场景下，符号表可能达到数 MB 量级（取决于符号数与片段长度），若符号表驻留在另一节点的显存中，解码首步的惰性展开就要先经 NIXL 做一次点对点传输，再进入本地 KV 写入。这笔传输落在首 token 时延的关键路径上，与代码补全场景的低延迟要求直接冲突。工程上的做法是把符号表按复用频次分层：高频符号表随前缀缓存一起驻留本地，低频表留在远端按需拉取，并用容量上限 $M$ 触发按频次淘汰。淘汰策略必须与并发批大小联合标定——批越大，单步内触发的符号展开越多，远端拉取的并发请求越容易打满 NIXL 通道，反过来拖慢整批的首 token 时延。</p>\n\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>压缩带来的通信变化</th><th>瓶颈触发条件</th></tr></thead><tbody><tr><td>TP</td><td>All-Reduce 量不变，计算侧缩小</td><td>计算通信比跌破隐藏阈值，TP 组内转为通信受限</td></tr><tr><td>EP</td><td>All-to-All 随 token 数近线性下降</td><td>专家并行度高、单卡专家计算已很短时，All-to-All 成为主项</td></tr><tr><td>PP</td><td>激活传递随 micro-batch token 数下降</td><td>流水气泡占比上升，stage 间空等加剧</td></tr><tr><td>符号表同步</td><td>新增元数据跨副本/跨节点传输</td><td>远端拉取落在首 token 路径，或并发展开打满 NIXL</td></tr></tbody></table>\n\n<p>展开歧义是通信侧的隐性代价。形式化约束要求 $\\mathrm{Expand}(\\mathcal{C}(x))=x$，输出前做还原校验，失败即回退原文路径。回退意味着该请求放弃压缩上下文、改走完整预填，其 token 量回到未压缩水平，在连续批处理中会突然抬高该 batch 的预填负载，并让原本按压缩后规模估算的 KV 预算瞬间失配。若回退发生在 TP 组内，激活切片的 All-Reduce 量随之回升，通信与显存同时被拉回未压缩档位；若回退请求集中在同一批，PP 的 stage 间负载倾斜会放大流水气泡。因此还原失败率必须作为容量规划的一等指标，与符号表膨胀速率、预填 token 节省比例并列监控，并在 SLO 中为符号展开延迟设上限，超限即回退，避免单请求的歧义拖垮整批的时延分布。</p>\n\n<p>最后落在拓扑选择上：符号压缩与分离式预填/解码正交，但它把预填侧的算力需求压低后，Prefill 节点的 GPU 利用率会先于 Decode 节点松下来，此时把节省的算力换成为更高的 TP 度并不划算——TP 度越高，固定 All-Reduce 开销占比越大，压缩收益被通信吃掉的比例越高。更合理的做法是维持较低 TP 度、把释放出的显存用于容纳更大的符号表与更长的展开窗口，让 KV 驻留随展开窗口而非序列长度增长这一性质真正兑现；跨节点扩展则交给 EP 与 PP，因为这两者的通信量随 token 数下降，与压缩方向一致。判断依据不是压缩率本身，而是压缩后单层计算时间是否仍显著大于该层在 NVLink 5 域内的 All-Reduce 时间——低于这条线，继续加并行度只会把瓶颈从算力搬到通信。</p>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-39\">三十九 · 精度塌陷：还原校验是唯一的硬闸门</h3>\n<p>符号压缩的精度风险与量化不同：量化把误差摊到每个权重与激活上，符号压缩把误差集中在“边界判定”这一个离散决策上。规则把一段跨文件上下文切成“可符号化”与“残差”两部分，切错一刀，展开结果就与原序列不等，形式化约束 <span class=\"formula-inline\">Expand(C(x))=x</span> 被破坏。这种破坏不是渐变而是阶跃：一个函数签名被误判为重复模板，展开时参数名被符号表中的旧版本覆盖，模型看到的上下文语义已经偏移，输出却仍然语法合法——这就是精度塌陷的典型形态，损失曲线看不出来，编译通过率却掉。</p>\n<p>工程上唯一可信的闸门是输出前的还原校验：对每个被引用的符号，比较展开片段与原始片段的规范化形式（去空白、统一注释符、标识符归一），不一致即判定该请求压缩失败并回退原文路径。校验本身有代价：它要在解码关键路径上多做一次片段比对，属于首 token 时延预算的固定开销；若把校验放在异步侧，则失败请求已经产出错误 token，回滚成本远高于前置校验。因此校验必须前置且同步，代价是每请求几毫秒量级的确定性开销，换来的是把“静默错误”转成“显式回退”。</p>\n<p>具体例子：仓库级补全请求携带三个文件的工具函数上下文，规则把两个同名但实现不同的 <code>parse_config</code> 合并为一个符号。还原校验在规范化后比对函数体哈希，发现不一致，请求回退原文路径，预填 token 量回到未压缩水平，但输出语义正确。这个回退本身就是诊断信号：同名不同实现是符号边界识别的系统性盲区，应触发规则修订而非单请求重试。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-40\">四十 · OOM 与符号表膨胀：容量上限要和批大小联合标定</h3>\n<p>符号压缩的显存账本有两层：活跃展开窗口的 KV，以及符号表本身的驻留。前者随展开窗口而非序列长度增长，这是收益来源；后者是新增的常驻元数据，且会随仓库规模单调增长。符号表容量上限 M 触发按复用频次淘汰低频符号，但淘汰策略与并发批大小耦合：批内多个请求共享同一符号表时，淘汰一个高频符号会让整批请求同时回退原文，预填量瞬间抬升，形成显存尖峰。这就是符号压缩特有的 OOM 路径——不是单请求太长，而是批内共享元数据被驱逐引发的集体回退。</p>\n<div class=\"formula\">$$KV_{\\text{peak}} \\approx B \\cdot W \\cdot L_{\\text{exp}} \\cdot d \\cdot b + S_{\\text{table}}(M)$$</div>\n<p>其中 B 为并发批大小，W 为每请求活跃展开窗口数，L_exp 为窗口长度，d 为头维，b 为每元素字节数，S_table 为符号表在容量 M 下的驻留。工程判断是：M 不能独立设定，必须与 B 和展开窗口上限一起做联合标定，把“最坏情况下整批回退”的预填量纳入显存预算。监控项应包含符号表膨胀速率（单位时间新增符号数）与淘汰触发频次；淘汰频次陡增说明 M 偏小或规则粒度过细，前者调容量，后者改规则。</p>\n<p>具体例子：agent 工具调用循环中，每轮请求都携带累积的调用历史，符号表跨轮复用本应降低预填，但若每轮都引入新的工具输出模板，符号表持续膨胀直至触顶，淘汰与新增交替发生，批内命中率抖动。定位方法是按轮次记录符号表命中率与淘汰计数，若命中率随轮次下降而淘汰计数上升，则判定为膨胀型抖动，处置是把工具输出模板的符号化粒度从“整段”降到“字段级”，减少符号数量而非扩大 M。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-41\">四十一 · 批抖动与尾延迟：展开开销进入首 token 预算</h3>\n<p>连续批处理下，批的组成每步都在变，符号压缩引入了一种新的抖动源：同一批内部分请求命中符号表走压缩路径，部分请求因校验失败回退原文路径，两条路径的预填 token 量相差数倍，导致批内计算量不均，调度器按 token 数配额切批时会把长路径请求推到后续步，尾延迟被拉长。这不是负载本身的方差，而是压缩路径二元性制造的方差。</p>\n<p>定位手段是给每个请求打路径标签（压缩命中/回退/未压缩），按标签分桶统计首 token 时延与预填 token 数。若回退桶的 P99 显著高于命中桶，且回退比例与批组成相关，则确认是批抖动而非单请求问题。处置有两条：其一，调度层按路径标签做亲和性分组，尽量让同路径请求同批，减少批内不均；其二，对展开开销设硬上限，超限即回退原文，把不可控的长尾转成可控的固定路径。</p>\n<p>具体例子：代码补全场景要求低延迟，符号展开需要在解码第一步惰性取出片段并拼接，若展开窗口跨多个符号引用，拼接开销随引用数线性增长。把引用数上限设为规则参数，超过即整请求回退，可将首 token 时延的方差压到与未压缩路径同一量级，代价是压缩命中率下降——这是 SLO 约束下的显式取舍，而非缺陷。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-42\">四十二 · 静默降级：三类信号必须同时看</h3>\n<p>符号压缩最危险的失败模式是静默降级：系统没有报错、没有回退、吞吐指标正常，但压缩收益已经被侵蚀。三种典型形态：其一，符号表命中率缓慢下降，压缩路径仍在走但残差序列变长，预填节省比例缩水；其二，还原校验通过率维持高位但校验本身被放宽（规范化过于宽松），歧义展开被放过；其三，展开窗口因规则粒度变粗而变长，KV 驻留回升。三者都不触发告警阈值，因为单看任何一项都在“正常范围”。</p>\n<p>监控必须把三类信号放在同一时间轴上对照：预填 token 节省比例、还原校验失败率、平均展开窗口长度。节省比例下降而失败率不变，指向符号表命中率问题；失败率上升而节省比例不变，指向规则边界问题；展开窗口变长而前两者不变，指向规则粒度问题。单独看任一指标都会漏判。工程上应把这三个量做成每批次聚合的派生指标，与批大小、并发数联动展示，因为它们的漂移往往由负载结构变化驱动而非规则本身。</p>\n<p>具体例子：跨仓库复用场景中，新仓库的代码风格与既有规则不匹配，符号识别命中率下降，残差序列变长，预填节省比例从高位滑落，但系统仍标记为“压缩生效”。若无节省比例的时间序列对照，这种降级会持续数天直到容量规划失准。定位后处置不是调阈值，而是为该仓库单独维护规则集，把规则维护成本显式化——这正是该方法代价集中在规则管理而非梯度计算的直接体现。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-43\">四十三 · 回滚：分级回退而非全局关闭</h3>\n<p>回滚策略要按失败模式分级，而不是一刀切关闭压缩。第一级是单请求回退：还原校验失败即走原文路径，影响面最小，代价是该请求预填量回到未压缩水平。第二级是批级隔离：某路径标签的回退率在滑动窗口内超阈值，调度器把该标签请求移出压缩批次，避免抖动扩散。第三级是规则级熔断：符号表膨胀速率或淘汰频次超限，暂停新增符号写入、保留既有符号表只读，让系统在不再恶化的状态下运行，为规则修订争取时间。第四级才是全局关闭压缩，仅在还原校验本身失效（校验逻辑 bug）时使用。</p>\n<p>分级回滚的关键是每一级都有明确的触发指标与恢复条件，且回退路径必须与压缩路径共享同一套 KV 预算核算，否则回退会把显存打爆。恢复条件应保守：批级隔离的恢复需要连续多个窗口回退率低于阈值，规则级熔断的恢复需要规则修订后在小流量灰度验证还原一致性。回滚不是运维动作而是容量动作，每一次回退都改变预填 token 量与 KV 驻留，容量规划必须把回退态作为独立档位建模。</p>\n<p>具体例子：一次规则修订引入新的注释模板符号，上线后还原校验失败率在特定文件类型上抬升，触发批级隔离，该文件类型请求全部走原文路径，吞吐下降但输出正确；随后定位到模板匹配把行内注释与块注释混判，修订规则后在灰度流量上验证校验通过率恢复，再逐批放开。整个过程压缩路径未全局关闭，SLO 未破，代价是隔离期间该文件类型的预填算力回到未压缩水平——这是可接受的确定性代价，优于静默降级带来的不可核验风险。</p>\n<p>需要强调的是，材料未给出任何失败率统计与定量实验结果，上述阈值与窗口长度均需在具体硬件档位（B200/B300 的 KV 预算）与 SLO 下自行标定。符号压缩的收益无法与 NVFP4/FP8 量化或前缀缓存做定量比较，其工程价值取决于规则维护成本能否被结构重复度高的代码场景摊薄；在跨语言、跨仓库泛化性未验证的前提下，分级回滚与三类信号联动监控是把不可核验风险转成可运维状态的最低要求。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-44\">四十四 · 失效边界：从还原校验到符号表膨胀的工程诊断</h3>\n<p>符号压缩的失效不是单一故障，而是一条从规则层传导到 KV 层的链。最上游是符号边界识别：规则把一段跨文件函数签名与注释模板抽象为符号 <code>s_i</code>，若边界切错，解码时 <code>Expand(s_i)</code> 会拼出与原文不等价的片段，产生展开歧义而非显式报错——这就是静默降级的来源。工程上唯一的兜底是输出前的还原校验，把形式约束 <code>Expand(C(x))=x</code> 变成运行时断言：对每个被引用的符号，比对展开片段与符号表登记的原文摘要，不一致即判定该请求压缩失败，整条请求回退原文路径重跑预填。代价是每请求多一次摘要比对与一次潜在的重预填，尾延迟上出现双峰；因此校验必须放在流式输出的首个 token 之前完成，否则回退发生在用户已看到部分输出之后，语义已污染。</p>\n<p>第二类失效是符号表膨胀。压缩收益取决于残差长度与符号表元数据之和是否显著小于原文，而符号表本身要参与前缀缓存命中判断、要跨请求驻留。设符号表容量上限为 <code>M</code>，命中率随仓库内符号复用频次分布衰减，当新符号写入速率超过按频次淘汰低频符号的速率时，表内低频符号挤占缓存元数据空间，KV 节省被元数据驻留抵消。监控指标应是膨胀速率 <code>d|C(x)|/dt</code> 与预填 token 节省比例的比值，而非单看压缩率；比值反转即触发容量回收。批抖动则来自符号展开的惰性特性：同一批内不同请求的活跃展开窗口长度差异大，解码步的 KV 驻留随窗口而非序列长度增长，导致批内显存需求不均，连续批处理在拼接时出现显存峰值抖动，表现为吞吐随批组成波动而非随并发单调上升。</p>\n<p>OOM 与尾延迟的定位要区分层次：OOM 若发生在预填前，多半是符号表元数据与残差序列叠加超出预算，属容量标定问题；若发生在解码中，则是展开窗口峰值未被批调度器感知，需把窗口长度作为调度约束传入。尾延迟尖峰优先查还原校验失败率与回退重跑次数，其次查符号展开开销是否挤占首 token 时延预算——代码补全场景对首 token 极敏感，展开延迟超限时必须回退原文以保证 SLO。回滚策略按粒度分级：单请求级回退原文路径；符号级将问题符号标记为不可压缩并写入黑名单；仓库级在还原失败率越限时整体关闭压缩层，退回纯前缀缓存加分离式预填的基线拓扑。下表给出诊断信号与动作的对应。</p>\n<table class=\"mini\"><thead><tr><th>信号</th><th>定位层</th><th>动作</th></tr></thead><tbody><tr><td>还原校验失败率上升</td><td>规则/边界识别</td><td>符号入黑名单，请求回退原文</td></tr><tr><td>符号表膨胀速率超过节省比例</td><td>元数据容量</td><td>按复用频次淘汰，收紧 M</td></tr><tr><td>批内展开窗口方差大</td><td>批调度</td><td>窗口长度入调度约束，拆批</td></tr><tr><td>首 token 时延超预算</td><td>展开开销</td><td>关闭惰性展开，回退原文</td></tr></tbody></table>\n<p>需要强调的是，材料未给出任何失败率统计与定量收益，上述阈值只能在具体 B200/B300 档位下按 SLO 实测标定；符号压缩的规则维护成本与符号表管理开销决定了它适合结构重复度高的代码仓库，跨语言、跨仓库的边界识别泛化性未经验证，把其效率结论直接外推到通用长文本推理属于不可核验的风险。</p>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-45\">四十五 · 论文口径的空缺：没有数字时如何建立可读的基准</h3>\n<p>这篇论文在评测层面是“空口径”的：材料明确未给出数据集名称、对比基线、吞吐/延迟/压缩率数字，也未给出消融。因此本部分不讨论“它比谁快多少”，而讨论一件事——当一篇论文只给出机制与形式化约束、不给出定量结果时，工程读者应当如何为它自建一套可核验的基准口径，并把它的收益放进 Blackwell 推理栈的真实代价结构里读。判断的起点是：符号压缩的收益只可能来自两处，预填 token 量的削减与 KV 驻留的削减；任何声称的效率提升若不能分解到这两个量上，就不可比。</p>\n<p>先把可测量的量写成显式形式。设原始请求序列长度为 <span class=\"inline-math\">L</span>，压缩后残差长度为 <span class=\"inline-math\">L_r</span>，符号表条目数为 <span class=\"inline-math\">n</span>，每条符号引用的平均展开长度为 <span class=\"inline-math\">\\(\\bar{e}\\)</span>，活跃展开窗口为 <span class=\"inline-math\">W</span>。则预填阶段的注意力计算量近似正比于 <span class=\"inline-math\">L_r+n</span> 而非 <span class=\"inline-math\">L</span>，而解码阶段驻留 KV 的长度上界为 <span class=\"inline-math\">W</span> 而非 <span class=\"inline-math\">L</span>：</p>\n<div class=\"formula\">$$L_{\\text{prefill}}\\approx L_r+n,\\qquad L_{\\text{kv}}\\lesssim W,\\qquad \\text{压缩比}\\;\\rho=\\frac{L}{L_r+n}$$</div>\n<p>这三个量分别对应三笔不同的系统代价：<span class=\"inline-math\">\\(L_{\\text{prefill}}\\)</span> 决定 TTFT 中的预填段，<span class=\"inline-math\">\\(L_{\\text{kv}}\\)</span> 决定单请求显存占用与可并发批大小，<span class=\"inline-math\">\\(\\rho\\)</span> 只是前两者的派生量、本身不是性能指标。论文只声称 <span class=\"inline-math\">\\(|\\mathcal{C}(x)|\\ll|x|\\)</span>，这等价于声称 <span class=\"inline-math\">\\(\\rho\\)</span> 大，但对 <span class=\"inline-math\">W</span> 与展开开销没有任何约束——而后者才是解码路径上真正决定 TPOT 的东西。</p>\n<p>具体例子：仓库级补全请求携带跨文件上下文，其中重复出现的函数签名与注释模板被抽象为符号，残差只保留本次编辑片段。若某请求 <span class=\"inline-math\">L</span> 很长而残差极短，则 <span class=\"inline-math\">\\(\\rho\\)</span> 很大、TTFT 的预填段显著缩短；但只要解码时需要展开的符号窗口 <span class=\"inline-math\">W</span> 仍然很长，KV 驻留并不会按 <span class=\"inline-math\">\\(\\rho\\)</span> 同比例下降。这就是“压缩比好看、显存不好看”的典型口径错位，也是本部分要建立的第一个读法：压缩比不能替代 KV 驻留量。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-46\">四十六 · 硬件档位：B200/B300 与 NVL72 上三笔代价的落点</h3>\n<p>论文未给出硬件档位与并行拓扑，部署方必须自行在 B200/B300 档位下标定 KV 预算。Blackwell 上符号压缩的三笔代价分别落在不同资源上，读数字时必须区分它们：预填 token 削减主要省的是 tensor core 的算力时间（SM100/SM103 的 tcgen05 MMA 与 TMEM 路径），体现为 TTFT 下降；KV 驻留削减省的是 HBM 容量与 KV 读写带宽，体现为可并发批大小上升与 TPOT 中的注意力读带宽下降；而符号表的识别、匹配与展开是标量/控制路径的工作，落在 SM 的通用管线与调度上，不占 MMA 吞吐却占指令发射与寄存器压力。</p>\n<p>因此同一份压缩收益在不同档位上不可直接换算。以 NVL72 机架为例，GB200/GB300 的 72 卡域内 NVLink 5 让分离式预填/解码拓扑可以把预填与解码放在不同卡组上，符号压缩与这种拓扑正交叠加：预填侧因 <span class=\"inline-math\">\\(L_{\\text{prefill}}\\)</span> 缩短而释放出的算力可以转化为更高的预填并发，解码侧因 <span class=\"inline-math\">\\(L_{\\text{kv}}\\)</span> 下降而释放的 HBM 可以转化为更大的连续批。但若部署是单卡或小规模 TP，释放出的预填算力无法跨卡转移，收益只体现在单请求 TTFT 上，吞吐几乎不动。这就是第二个读法：同一压缩率在 NVL72 与单卡上的吞吐含义不同，跨档位引用数字必须先声明拓扑。</p>\n<p>具体机制上，符号表本身作为可缓存元数据参与前缀缓存命中判断，这意味着它的存放位置也有代价：符号表若常驻 HBM，则与 KV 争夺同一容量池；若放在 host 侧，则每次展开都要经 PCIe 往返，把解码路径变成带宽受限。工程判断是：符号表应按仓库维度分片、按复用频次淘汰（容量上限 <span class=\"inline-math\">M</span> 触发低频淘汰），并把“符号表命中”与“前缀缓存命中”合并为一次元数据查询，避免两次独立查表把解码首步的调度延迟抬高。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-47\">四十七 · batch 与并发：符号表容量与展开窗口联合标定</h3>\n<p>论文未给出批大小与并发，材料只说需按符号表容量与展开窗口估算显存驻留上限。这句话给出了正确的标定顺序：先定 <span class=\"inline-math\">W</span>，再定 <span class=\"inline-math\">M</span>，最后反推可并发批 <span class=\"inline-math\">B</span>。设每 token 每层 KV 字节数为 <span class=\"inline-math\">k</span>、层数为 <span class=\"inline-math\">N_l</span>、可用 KV 显存为 <span class=\"inline-math\">\\(S_{\\text{kv}}\\)</span>，则单请求驻留与批上界为：</p>\n<div class=\"formula\">$$S_{\\text{req}}\\approx k\\cdot N_l\\cdot W+S_{\\text{sym}},\\qquad B_{\\max}\\approx\\left\\lfloor \\frac{S_{\\text{kv}}}{S_{\\text{req}}}\\right\\rfloor$$</div>\n<p>其中 <span class=\"inline-math\">\\(S_{\\text{sym}}\\)</span> 是分摊到单请求的符号表元数据开销。这个式子暴露了符号压缩的一个反直觉性质：<span class=\"inline-math\">W</span> 越小，<span class=\"inline-math\">\\(B_{\\max}\\)</span> 越大，但 <span class=\"inline-math\">W</span> 太小会迫使解码频繁回查符号表、增加展开次数与还原校验次数，把省下的带宽换成控制开销。因此 <span class=\"inline-math\">W</span> 不是越小越好，它与 <span class=\"inline-math\">M</span> 必须与并发批联合标定——这正是材料所说“容量上限与淘汰策略需与并发批大小联合标定”的工程含义。</p>\n<p>具体例子：假设某仓库级服务把 <span class=\"inline-math\">W</span> 设为覆盖一次编辑片段的展开长度，则 <span class=\"inline-math\">\\(S_{\\text{req}}\\)</span> 由 <span class=\"inline-math\">W</span> 主导，<span class=\"inline-math\">\\(B_{\\max}\\)</span> 随 <span class=\"inline-math\">W</span> 反比变化；若为追求更大 <span class=\"inline-math\">B</span> 而压缩 <span class=\"inline-math\">W</span>，解码会在符号边界处反复展开，TPOT 的尾部延迟上升。连续批处理下这种抖动会被放大：一个请求的展开停顿会占住调度槽，拖累同批其他请求的 token 间隔。因此读这篇论文的吞吐数字（若有）时必须问：<span class=\"inline-math\">W</span> 与 <span class=\"inline-math\">M</span> 取多少、批是否连续、展开停顿是否计入 TPOT 的分位数。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-48\">四十八 · 指标分解：TTFT、TPOT、吞吐、显存、功耗各自归谁</h3>\n<p>把符号压缩的收益按指标拆开，才能判断哪些提升可比。TTFT 由排队、预填、首步解码组成，符号压缩只作用于预填段，且只在 <span class=\"inline-math\">\\(\\rho\\)</span> 显著大于 1 时才有可见收益；若请求本身重复度低，<span class=\"inline-math\">\\(L_r\\approx L\\)</span>，预填段几乎不变，TTFT 收益趋零。TPOT 由每步的注意力读带宽、MMA 时间与展开/校验开销组成，符号压缩降低的是注意力读带宽那一项，但新增了展开与还原校验两项，二者相抵后的净收益必须实测，材料未给出该净收益。</p>\n<p>吞吐要分两种口径读：token 吞吐（tokens/s）与请求吞吐（req/s）。符号压缩对前者的提升来自 <span class=\"inline-math\">\\(B_{\\max}\\)</span> 上升，对后者的提升还取决于每请求平均输出长度是否因压缩而改变——论文声称不改变推理语义，故输出长度应不变，请求吞吐的提升应完全来自并发上界。显存侧要区分“峰值”与“稳态”：符号表在请求进入时生成，峰值出现在符号表写入与残差预填同时驻留的瞬间，稳态则是展开窗口驻留；只报稳态 KV 节省而不报峰值，会掩盖符号表膨胀带来的瞬时压力。功耗侧，预填算力削减降低的是 MMA 密集段的功耗，而展开与校验是标量密集段，能效比不同，整机功耗的下降幅度不能按算力削减比例线性外推。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>符号压缩的作用点</th><th>可比性前提</th></tr></thead><tbody><tr><td>TTFT</td><td>预填 token 量 <span class=\"inline-math\">L_r+n</span></td><td>同一 <span class=\"inline-math\">\\(\\rho\\)</span>、同一预填并行拓扑</td></tr><tr><td>TPOT</td><td>注意力读带宽 vs 展开/校验开销</td><td>同一 <span class=\"inline-math\">W</span>、展开停顿计入分位数</td></tr><tr><td>吞吐</td><td>并发上界 <span class=\"inline-math\">\\(B_{\\max}\\)</span></td><td>同一 <span class=\"inline-math\">M</span>、同一连续批策略</td></tr><tr><td>显存</td><td>稳态 <span class=\"inline-math\">W</span> 与峰值符号表</td><td>峰值与稳态分别报告</td></tr><tr><td>功耗</td><td>MMA 密集段削减</td><td>整机而非单卡、含标量段</td></tr></tbody></table>\n<p>具体例子：一个工具调用循环中的 agent 请求，符号表可跨轮复用，降低重复预填成本——此时 TTFT 的收益体现在第 2 轮及以后，而第 1 轮因需生成符号表反而可能略慢。若基准只测单轮冷启动，就会得出“无收益”的结论；若只测热符号表命中，则会高估收益。可比的口径必须声明轮次分布与符号表命中率。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-49\">四十九 · 哪些提升不可比：四类口径陷阱</h3>\n<p>第一类陷阱是基线缺失下的自比。论文未给基线，若把“压缩后 vs 压缩前”当作提升，那只是机制自证，不能与 NVFP4/FP8 量化或前缀缓存做定量比较——量化削减的是每字节成本，前缀缓存削减的是重复预填，符号压缩削减的是重复存储与重复预填的 token 量，三者作用维度不同，收益不可直接相加或相除。第二类陷阱是压缩比冒充吞吐：<span class=\"inline-math\">\\(\\rho\\)</span> 是输入侧比值，吞吐是输出侧速率，二者之间隔着 <span class=\"inline-math\">W</span>、<span class=\"inline-math\">M</span> 与调度策略。第三类陷阱是冷热混测：符号表命中率不同，同一服务的 TTFT 分布会双峰化，均值无意义，必须报分位数并声明命中率。</p>\n<p>第四类陷阱是失败路径不计入。形式化约束要求 <span class=\"inline-math\">\\(\\mathrm{Expand}(\\mathcal{C}(x))=x\\)</span>，输出前做还原校验，失败则回退原文路径；符号边界识别错误会产生展开歧义。回退意味着该请求实际走了未压缩路径，其延迟与显存回到基线水平，若基准把回退请求剔除，就等于把最坏情况从统计中删掉。可比的口径必须把回退率作为一等指标，并与符号表膨胀速率、预填 token 节省比例一起监控。材料明确缺少失败率统计，因此任何引用其效率结论的做法都存在无法核验的风险。</p>\n<p>具体机制上，回退路径的设计决定尾延迟：若回退在解码中途触发，已驻留的展开 KV 需要作废并重算原文预填，这一次重算的代价可能超过此前所有请求节省的总和。工程判断是把还原校验前移到预填结束、解码开始之前，用一次规则校验换取整段解码路径的确定性；代价是预填段增加一次校验开销，收益是消除解码中途回退的长尾。这一取舍在 SLO 约束下应显式建模：设回退概率为 <span class=\"inline-math\">p_f</span>、回退重算代价为 <span class=\"inline-math\">C_f</span>，则期望尾延迟增量约为 <span class=\"inline-math\">\\(p_f\\cdot C_f\\)</span>，只有当压缩带来的稳态节省大于该期望增量时，压缩才在 SLO 意义上划算。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-50\">五十 · 自建基准的最小清单与工程落点</h3>\n<p>在没有论文数字的前提下，工程方要建立可核验基准，最小清单应包含：负载的重复度分布（决定 <span class=\"inline-math\">\\(\\rho\\)</span> 的实际取值）、符号表命中率与轮次分布（决定 TTFT 收益出现在哪一段）、<span class=\"inline-math\">W</span> 与 <span class=\"inline-math\">M</span> 的取值及淘汰策略、回退率与回退触发位置、以及峰值与稳态显存分别报告。硬件侧必须声明 B200/B300 档位、TP/EP 拓扑、是否处于 NVL72 域内、预填与解码是否分离。指标侧必须同时给出 TTFT 与 TPOT 的分位数、tokens/s 与 req/s 两种吞吐、以及整机功耗而非单卡功耗。</p>\n<p>读法上有一条硬规则：任何符号压缩的收益数字，只有在“同一硬件档位、同一 <span class=\"inline-math\">W</span>/<span class=\"inline-math\">M</span>、同一回退策略、同一命中率”四个条件下才可横向比较；缺任一条件，数字只能作为机制存在的证据，不能作为选型依据。论文的贡献在于给出可逆性约束这一可核验依据，而不在于给出效率幅度；因此它的正确用法是把形式化校验当作工程护栏，把收益幅度留给部署方在具体 SLO 下实测。</p>\n<p>最后落在一个具体机制上：符号表淘汰与展开窗口的联动。容量上限 <span class=\"inline-math\">M</span> 触发按复用频次淘汰低频符号时，被淘汰符号若仍被在途请求引用，展开会失败并触发回退；因此淘汰必须与在途请求的引用计数绑定，而不是纯按频次。工程判断是：把符号表当作带引用计数的缓存来管理，淘汰延迟到引用归零，代价是符号表稳态占用略高于纯频次策略，收益是消除“淘汰—回退”这一最隐蔽的尾延迟来源。这一判断不依赖论文的任何数字，只依赖它给出的可逆性约束与惰性展开结构。</p>\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-51\">五十一 · 迁移到非代码负载：符号密度决定收益上限</h3>\n<p>这套方案的经济性完全建立在“重复片段占比”上。压缩层在预填前把重复出现的代码结构与自然语言模板抽象为符号引用，残差序列只保留本次请求特有部分，预填阶段仅对残差与符号表计算注意力。形式化约束 <span class=\"formula\">$$\\mathcal{C}(x)=\\{\\,(s_i,\\,r_i)\\,\\}_{i=1}^{n},\\quad \\mathrm{Expand}(\\mathcal{C}(x))=x,\\;\\; |\\mathcal{C}(x)|\\ll|x|$$</span> 中真正承重的是最后那个不等式：只有当符号表加残差显著短于原文时，预填 token 与 KV 驻留才会下降。仓库级代码天然满足这一点——函数签名、许可证头、注释模板、跨文件重复的接口声明反复出现，符号识别与模式匹配能稳定命中。迁到通用长文本推理时，重复结构退化为修辞模板与引用格式，符号密度骤降，残差序列占比上升，压缩比趋近于 1，此时压缩层只增加了一次扫描开销而没有换来 KV 节省。判断标准不是“文本有多长”，而是“可被规则稳定识别的重复片段占多少 token”。工程上应在接入前对目标负载做重复度统计，把压缩比低于阈值的请求直接旁路到原文路径，避免为低收益负载支付符号表维护成本。</p>\n<p>跨语言迁移是同一问题的尖锐版本。符号识别依赖人工规则，规则集对某一种语言的缩进、命名与注释惯例拟合得越好，换到另一种语言时符号边界识别错误率越高。边界识别错误直接产生展开歧义：符号引用指向的片段与解码时展开的原文不一致，还原校验失败，请求回退原文路径。回退本身不破坏正确性，但它把延迟预算吃掉了——代码补全要求低延迟，符号展开开销必须计入首 token 时延，超限即回退，于是高歧义负载的实际表现是“先付扫描与匹配的代价，再付原文预填的代价”。因此跨语言部署的正确做法是按语言分规则集、分符号表，而不是用一套规则覆盖多语言仓库。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-52\">五十二 · 与量化、前缀缓存叠加时的次序与冲突</h3>\n<p>符号压缩与前缀缓存正交，但正交不等于无交互。符号表作为可缓存元数据参与前缀缓存命中判断，仓库级复用直接复用符号表而非原文，跨请求避免重复预填——这是叠加收益最明显的路径：同一仓库的连续请求共享符号表，预填只处理残差。问题在于命中粒度。前缀缓存按 token 前缀匹配，而符号压缩改变了送入预填的序列形态，压缩后的残差序列前缀与原文前缀不再一一对应。若缓存键仍以原文前缀构造，压缩请求无法命中；若以压缩形态构造，则未压缩请求无法复用同一份缓存。工程判断是：在压缩层与预填之间显式维护两套缓存命名空间，符号表命中走压缩路径，未命中走原文路径，不要让两条路径争抢同一份前缀缓存条目。</p>\n<p>与 NVFP4/FP8 量化叠加时，冲突点不在数值而在生命周期。量化压缩的是每个驻留元素的位宽，符号压缩压缩的是驻留元素的数量；两者相乘才是 KV 预算的实际下降幅度。但符号展开是惰性的，活跃 KV 仅覆盖当前展开窗口，窗口随解码推进而滑动，被淘汰的展开片段其量化后的 KV 需要重新计算或从符号表重建。若量化 KV 的换入换出带宽开销高于重建开销，惰性展开反而增加数据搬运。因此在带宽受限的档位上，应优先让展开窗口内的 KV 保持驻留、窗口外直接丢弃并以符号表重建，而不是把量化 KV 换出到远端再换回。这条判断在 B200/B300 档位上需要按实际 HBM 带宽与展开窗口大小标定，材料未给出数字，只能定性：重建成本随符号片段长度线性增长，换出成本随 KV 位宽与链路带宽变化，两者交叉点决定策略。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-53\">五十三 · 规模上限：符号表容量 M 与并发批大小的联合约束</h3>\n<p>符号表不是免费的。容量上限 M 触发按复用频次淘汰低频符号，符号表膨胀会抵消压缩收益。设单请求符号表条目数为 <span class=\"formula\">$$k$$</span>、平均符号引用长度为 <span class=\"formula\">$$l$$</span>、并发批大小为 <span class=\"formula\">$$B$$</span>，则符号表元数据的驻留量随 <span class=\"formula\">$$B \\times k \\times l$$</span> 增长，而 KV 节省量随展开窗口而非序列长度增长。当 <span class=\"formula\">$$B$$</span> 增大时，符号表元数据与活跃展开窗口的 KV 同时膨胀，压缩收益被摊薄；当 <span class=\"formula\">$$B$$</span> 减小时，吞吐下降。这就是规模上限的来源：存在一个批大小区间，使得单位吞吐的显存占用最低，超出该区间后符号表管理开销压过 KV 节省。容量上限与淘汰策略必须与并发批大小联合标定，单独调 M 没有意义——M 定得大，低频符号长期驻留挤占元数据空间；M 定得小，跨请求复用率下降，前缀缓存命中带来的预填节省消失。</p>\n<p>监控口径应覆盖三项：符号还原失败率、符号表膨胀速率、预填 token 节省比例。前两项是正确性与成本的守门指标，第三项是收益指标。三者联合读出的工程判断是：若还原失败率上升而预填节省比例不升，说明规则集与负载不匹配，应收缩符号识别范围而非放宽阈值；若膨胀速率高于预填节省比例的增长，说明淘汰策略失效，应下调 M 并接受复用率损失。材料未给出失败率统计与敏感性数据，因此这些阈值只能在具体硬件档位与 SLO 下实测确定，不能引用论文结论直接上线。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-54\">五十四 · 不适用的边界：语义等价无法规则化的场景</h3>\n<p>形式化约束要求 Expand(C(x))=x，这条约束的可核验性依赖“符号边界可由规则判定”。一旦负载中存在语义等价但字面不同的片段——变量重命名后的同构代码、改写过的注释、语义相同而措辞不同的自然语言——规则无法把它们归为同一符号，压缩比下降；更危险的是规则误判，把字面相似而语义不同的片段归为同一符号，展开后语义漂移，还原校验只能发现字面不一致，发现不了语义不一致。因此该方法适用于结构重复度高、字面重复与语义重复高度重合的代码场景，不适用于以语义改写为主的自然语言长文本推理，也不适用于需要跨请求做语义级去重的场景。判断标准是：字面重复率与语义重复率的差距越小，方案越安全。</p>\n<p>另一条边界是规则维护成本。方法不依赖训练或微调，可直接作用于已部署模型，代价集中在规则维护与符号表管理而非梯度计算。这意味着收益不随模型规模自动放大：换一个更强的模型，符号识别规则不会自动适配新的代码风格与注释习惯，规则集需要重新标定。对于快速迭代的仓库，规则维护的人力成本可能超过 KV 节省带来的容量收益。工程判断是：只在仓库结构稳定、跨文件重复模式长期不变的场景部署，把规则集当作与模型版本解耦的独立资产维护，并在仓库结构变更时同步更新规则，否则还原失败率会随仓库演化单调上升。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-55\">五十五 · 部署决策：三条可执行的判断线</h3>\n<p>第一条线是负载筛选。接入前统计目标负载的重复片段 token 占比与跨请求符号表命中率，前者决定单请求压缩比，后者决定前缀缓存复用收益。两项都低时，压缩层只增加扫描与匹配开销，应直接旁路。第二条线是延迟预算分配。符号展开开销计入首 token 时延，必须设上限，超限回退原文路径；回退率本身是监控指标，回退率上升说明规则集与负载漂移，而不是展开逻辑有 bug。第三条线是容量规划。符号表元数据驻留量与活跃展开窗口 KV 共同构成显存占用，容量上限 M 与并发批大小联合标定，以单位吞吐显存占用最低为目标，而不是以单请求压缩比最高为目标。</p>\n<p>把这三条线落到具体机制上：压缩层位于请求进入预填之前，输出前做符号还原校验，失败则回退原文路径；符号表作为元数据参与前缀缓存命中判断；解码时按符号引用惰性展开，KV cache 仅驻留当前活跃展开窗口。这套结构的收益上限由负载重复度决定，成本下限由规则维护与符号表管理决定，两者之间的差额才是可部署的空间。材料未给出任何吞吐、延迟或压缩率数字，因此任何“提升效率”的引用都必须标注为未经核验的声称；在 B200/B300 档位上，唯一可靠的落地方式是先做小流量旁路对照，用预填 token 节省比例与还原失败率两条曲线决定是否扩大流量，而不是先信结论再找证据。</p>\n\n<h3 id=\"paper-enhancing-large-language-model-effic-2025-sec-56\">五十六 · 迁移的代价在规则面，不在算子面</h3>\n<p>这套方案对硬件的假设极轻：压缩层位于预填之前，只做符号识别与模式匹配，不引入新的矩阵乘形态，也不要求 tcgen05 或 TMEM 的特殊排布。因此迁到 B200/B300 或 GB200 NVL72 时，算子层面几乎不用改，NVFP4/FP8 量化、前缀缓存、分离式预填都能原样叠加。真正要重写的是符号系统本身：规则由人工设定而非学习得到，换一种语言、换一个仓库的命名习惯，模式匹配阈值就得重新标定。跨语言与跨仓库的泛化性在材料中未经验证，这意味着迁移成本随目标领域的结构规整度线性上升，而不是随模型规模上升。</p>\n<p>失效条件可以写成一个简单的判据。设符号表容量上限为 M，请求中可符号化片段占比为 ρ，单次展开窗口长度为 w，则压缩后预填 token 量近似为 |x|(1−ρ)+|𝒞(x)|，而 KV 驻留上限由 w 而非序列长度决定。当 ρ 低于某个门槛、或符号表膨胀速率使 |𝒞(x)| 逼近 M 时，淘汰低频符号会触发反复重压缩，收益被管理开销吃掉。此时应直接回退原文路径——材料给出的兜底机制正是还原校验失败即回退，这条路径同时适用于收益不足的情形。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>需改动</th><th>主要风险</th></tr></thead><tbody><tr><td>同语言、结构重复度高的代码仓库</td><td>仅调阈值</td><td>符号表膨胀</td></tr><tr><td>跨语言代码库</td><td>重写识别规则</td><td>边界歧义、展开不一致</td></tr><tr><td>通用长文本推理</td><td>规则基本失效</td><td>ρ 过低，压缩不抵开销</td></tr></tbody></table>\n<p>规模上限不在模型侧，而在符号表的元数据管理侧。符号表要参与前缀缓存命中判断，其条目数随仓库规模增长，容量上限 M 与并发批大小必须联合标定；仓库级复用越深，符号表越像一份需要版本化的一致性视图，跨请求复用时任何规则变更都会使旧符号表失效。工程判断是：把该方案当作代码补全与 agent 工具调用循环里的 KV 削减插件，用还原失败率、符号表膨胀速率、预填 token 节省比例三条指标守住 SLO；通用长文本场景下，它的规则维护成本高于前缀缓存与量化带来的确定性收益，不应作为默认路径。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Enhancing Large Language </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Model Efficien…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Enhancing Large Languag… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出可核验的吞吐、延迟或压缩率数字，仅能确认方法以形式化符号压缩为手…</td></tr><tr><td>消融</td><td>材料未给出消融实验，符号表容量、模式匹配阈值与展开策略的敏感性均无数据。</td></tr><tr><td>局限</td><td>材料未给出实验规模与失败率统计；符号边界识别依赖规则，跨语言与跨仓库泛化性…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-enhancing-large-language-model-effic-2025 · 共 9 个片段</p>\n";break;}}})();
